    {
      "path": "electron/llm/openai-provider.ts",
      "content": "import { InBandReasoningStream, ILLMProvider, LLMGenerateOptions, LLMResponse, LLMStreamOptions } from './provider.interface'\nimport type { LLMFinishReason, ModelProfile, TokenUsage } from '../../src/shared/ipc-channels'\nimport { resolveOpenAIChatCompletionsUrl } from './openai-compatible-endpoint'\nimport { VisibleStreamFilter } from './visible-stream'\nimport { resolveModelProfileReasoningMapping } from '../../src/shared/provider-presets'\nimport { version as appVersion } from '../../package.json'\nimport { StreamTransportDiagnostics } from './transport-diagnostics'\nimport { providerFailureCode } from './provider-context-length'\n\nconst OPENCODE_GO_USER_AGENT = `ai-novel-writer/${appVersion}`\n\nfunction isOpencodeGoBaseUrl(baseUrl: string): boolean {\n  try {\n    const endpoint = new URL(baseUrl.trim())\n    const configuredPath = endpoint.pathname.replace(/\\/+$/u, '')\n    return endpoint.protocol === 'https:'\n      && endpoint.hostname === 'opencode.ai'\n      && (configuredPath === '/zen/go' || configuredPath.startsWith('/zen/go/'))\n  } catch {\n    return false\n  }\n}\n\n// opencode Go requires a stable per-conversation session id for routing and\n// prompt caching. The caller supplies that conversation scope; a missing scope\n// degrades to a per-request id so one-off operations never share session\n// affinity with creative runs.\n\nexport class OpenAIProvider implements ILLMProvider {\n  private normalizeFinishReason(reason: string | null | undefined): LLMFinishReason {\n    if (reason === 'stop') return 'stop'\n    if (reason === 'length') return 'length'\n    if (reason === 'model_context_window_exceeded') return 'length'\n    if (reason === 'content_filter') return 'content_filter'\n    if (reason === 'sensitive') return 'content_filter'\n    if (reason === 'network_error') return 'error'\n    return 'unknown'\n  }\n\n  private stripThinking(content: string): string {\n    return content\n      .replace(/<think>[\\s\\S]*?(?:<\\/think>|$)/gi, '')\n      .replace(/^[\\s\\S]*?<\\/think>\\s*/i, '')\n      .replace(/<\\/?think>/gi, '')\n      .trim()\n  }\n\n  private buildRequestBody(\n    model: ModelProfile,\n    messages: Array<{ role: string; content: string }>,\n    opts: LLMGenerateOptions,\n    stream: boolean,\n  ): Record<string, unknown> {\n    const isNovelAI = model.provider === 'novelai'\n    const body: Record<string, unknown> = {\n      model: model.modelName,\n      messages,\n      [opts.outputTokenParameter ?? 'max_tokens']: opts.maxTokens ?? model.maxTokens,\n      stream,\n    }\n\n    // Temperature has already been resolved by generation-parameter-policy.\n    // Never fall back to model.temperature here: undefined is an intentional\n    // instruction to omit the field for provider/model combinations that own it.\n    if (opts.temperature !== undefined) {\n      body.temperature = opts.temperature\n    }\n\n    if (opts.reasoning?.adapter === 'openai-reasoning-effort' && !isNovelAI) {\n      body.reasoning_effort = opts.reasoning.reasoningEffort\n    }\n\n    if (opts.reasoning?.adapter === 'openai-thinking-budget' && !isNovelAI\n      && resolveModelProfileReasoningMapping(model)?.adapter === 'openai-thinking-budget') {\n      body.enable_thinking = opts.reasoning.thinkingBudget > 0\n      // A disabled request omits the numeric field: zero need not be a legal provider budget.\n      if (opts.reasoning.thinkingBudget > 0) body.thinking_budget = opts.reasoning.thinkingBudget\n    }\n\n    if (opts.reasoning?.adapter === 'siliconflow-v4-thinking'\n      && resolveModelProfileReasoningMapping(model)?.adapter === 'siliconflow-v4-thinking') {\n      body.enable_thinking = true\n      body.reasoning_effort = opts.reasoning.reasoningEffort\n    }\n\n    if (opts.reasoning?.adapter === 'deepseek-v4-thinking'\n      && resolveModelProfileReasoningMapping(model)?.adapter === 'deepseek-v4-thinking') {\n      body.thinking = { type: opts.reasoning.thinking }\n      if (opts.reasoning.thinking === 'enabled' && opts.reasoning.reasoningEffort !== undefined) {\n        body.reasoning_effort = opts.reasoning.reasoningEffort\n      }\n    }\n\n    if (opts.responseFormat && !isNovelAI) {\n      body.response_format = opts.responseFormat\n    }\n\n    // The OpenAI streaming API only sends the final usage chunk when this is\n    // explicitly requested. Keep NovelAI's narrower compatibility payload.\n    if (stream && !isNovelAI) {\n      body.stream_options = { include_usage: true }\n    }\n\n    return body\n  }\n\n  private buildRequestHeaders(model: ModelProfile, conversationId?: string): Record<string, string> {\n    const headers: Record<string, string> = {\n      'Content-Type': 'application/json',\n      'Authorization': `Bearer ${model.apiKey}`,\n    }\n    if (isOpencodeGoBaseUrl(model.baseUrl)) {\n      headers['x-opencode-session'] = conversationId || crypto.randomUUID()\n      headers['User-Agent'] = OPENCODE_GO_USER_AGENT\n    }\n    return headers\n  }\n\n  async generate(model: ModelProfile, messages: Array<{ role: string; content: string }>, opts: LLMGenerateOptions): Promise<LLMResponse> {\n    try {\n      const url = resolveOpenAIChatCompletionsUrl(model.baseUrl, model.provider)\n      const body = this.buildRequestBody(model, messages, opts, false)\n\n      const res = await fetch(url, {\n        method: 'POST',\n        headers: this.buildRequestHeaders(model, opts.conversationId),\n        body: JSON.stringify(body),\n        signal: opts.signal,\n      })\n\n      if (!res.ok) {\n        const text = await res.text()\n        return { success: false, content: '', finishReason: 'error', error: 'LLM_REQUEST_FAILED', httpFailure: { status: res.status, body: text } }\n      }\n\n      const data = await res.json() as {\n        choices: Array<{\n          message: { content: string; reasoning_content?: string }\n          finish_reason?: string | null\n        }>\n        usage?: { prompt_tokens: number; completion_tokens: number; total_tokens: number }\n      }\n\n      const finalContent = this.stripThinking(data.choices?.[0]?.message?.content ?? '')\n      const finishReason = this.normalizeFinishReason(data.choices?.[0]?.finish_reason)\n      const usage = data.usage ? {\n        promptTokens: data.usage.prompt_tokens,\n        completionTokens: data.usage.completion_tokens,\n        totalTokens: data.usage.total_tokens,\n      } : undefined\n\n      if (finishReason === 'stop') {\n        return {\n          success: true,\n          content: finalContent,\n          finishReason,\n          usage,\n        }\n      }\n\n      return {\n        success: false,\n        content: finalContent,\n        finishReason,\n        error: 'LLM_RESPONSE_INCOMPLETE',\n        usage,\n      }\n    } catch (error) {\n      return { success: false, content: '', finishReason: 'error', error: String(error) }\n    }\n  }\n\n  async generateStream(model: ModelProfile, messages: Array<{ role: string; content: string }>, opts: LLMStreamOptions): Promise<void> {\n    const transport = new StreamTransportDiagnostics(opts.onDiagnostics)\n    let fullText = ''\n    const visible = new VisibleStreamFilter()\n    const reasoning = (chunk: string) => { transport.output('reasoningEvents'); opts.onReasoning?.(chunk) }\n    const inBandReasoning = new InBandReasoningStream(reasoning)\n    let usage: TokenUsage | undefined\n    let reader: ReadableStreamDefaultReader<Uint8Array> | undefined\n    let protocolError: string | undefined\n    const fail = (error: string) => {\n      const visibleCandidate = opts.visibleOnly ? visible.text : this.stripThinking(fullText)\n      opts.onError(error, visibleCandidate || undefined, usage)\n    }\n\n    try {\n      const url = resolveOpenAIChatCompletionsUrl(model.baseUrl, model.provider)\n      const body = this.buildRequestBody(model, messages, opts, true)\n\n      const res = await transport.response(fetch(url, {\n        method: 'POST',\n        headers: this.buildRequestHeaders(model, opts.conversationId),\n        body: JSON.stringify(body),\n        signal: opts.signal,\n      }))\n\n      if (!res.ok) {\n        transport.fail('HTTP_ERROR')\n        fail(await providerFailureCode(res, opts.signal))\n        return\n      }\n\n      reader = res.body?.getReader()\n      if (!reader) {\n        transport.fail('RESPONSE_BODY_MISSING')\n        fail('LLM_STREAM_UNREADABLE')\n        return\n      }\n      transport.streaming()\n\n      const decoder = new TextDecoder()\n      let isThinking = false\n      let lineBuffer = ''\n      let dataLines: string[] = []\n      let sawDone = false\n      let finishReason: LLMFinishReason = 'unknown'\n      let fatalError: string | null = null\n\n      const processEvent = (data: string) => {\n        if (fatalError || sawDone) return\n        const json = data.trim()\n        if (!json) return\n        if (json === '[DONE]') {\n          sawDone = true\n          return\n        }\n\n        let parsed: unknown\n        try {\n          parsed = JSON.parse(json)\n        } catch {\n          fatalError = 'LLM_STREAM_INVALID'\n          return\n        }\n\n        if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {\n          fatalError = 'LLM_STREAM_INVALID'\n          return\n        }\n        const payload = parsed as Record<string, unknown>\n        if (Object.hasOwn(payload, 'error')) {\n          fatalError = 'LLM_STREAM_PROVIDER_ERROR'\n          return\n        }\n\n        const reportedUsage = payload.usage\n        if (reportedUsage !== null && typeof reportedUsage === 'object' && !Array.isArray(reportedUsage)) {\n          const rawUsage = reportedUsage as Record<string, unknown>\n          const details = rawUsage.completion_tokens_details\n          const reasoning = details && typeof details === 'object' && !Array.isArray(details)\n            ? (details as Record<string, unknown>).reasoning_tokens : undefined\n          opts.onUsageEvidence?.({\n            usage: {\n              promptTokens: typeof rawUsage.prompt_tokens === 'number' ? rawUsage.prompt_tokens : null,\n              completionTokens: typeof rawUsage.completion_tokens === 'number' ? rawUsage.completion_tokens : null,\n              totalTokens: typeof rawUsage.total_tokens === 'number' ? rawUsage.total_tokens : null,\n            },\n            reasoningTokens: typeof reasoning === 'number' ? reasoning : null,\n            accounting: 'included-in-completion', totalIncludesReasoning: true, protocol: 'openai',\n          })\n          if (\n            typeof rawUsage.prompt_tokens === 'number'\n            && typeof rawUsage.completion_tokens === 'number'\n            && typeof rawUsage.total_tokens === 'number'\n          ) {\n            usage = {\n              promptTokens: rawUsage.prompt_tokens,\n              completionTokens: rawUsage.completion_tokens,\n              totalTokens: rawUsage.total_tokens,\n            }\n          }\n        }\n\n        if (payload.choices === undefined) return\n        if (!Array.isArray(payload.choices)) {\n          fatalError = 'LLM_STREAM_INVALID'\n          return\n        }\n        const rawChoice = payload.choices[0]\n        if (rawChoice === undefined) return\n        if (rawChoice === null || typeof rawChoice !== 'object' || Array.isArray(rawChoice)) {\n          fatalError = 'LLM_STREAM_INVALID'\n          return\n        }\n        const choice = rawChoice as Record<string, unknown>\n        if (choice.finish_reason !== undefined && choice.finish_reason !== null) {\n          if (typeof choice.finish_reason !== 'string') {\n            fatalError = 'LLM_STREAM_INVALID'\n            return\n          }\n          finishReason = this.normalizeFinishReason(choice.finish_reason)\n        }\n\n        if (choice.delta === undefined) return\n        if (choice.delta === null || typeof choice.delta !== 'object' || Array.isArray(choice.delta)) {\n          fatalError = 'LLM_STREAM_INVALID'\n          return\n        }\n        const delta = choice.delta as Record<string, unknown>\n        if (delta.reasoning_content !== undefined && delta.reasoning_content !== null\n          && typeof delta.reasoning_content !== 'string') {\n          fatalError = 'LLM_STREAM_INVALID'\n          return\n        }\n        if (delta.content !== undefined && delta.content !== null && typeof delta.content !== 'string') {\n          fatalError = 'LLM_STREAM_INVALID'\n          return\n        }\n\n        if (delta.reasoning_content) reasoning(delta.reasoning_content as string)\n        if (typeof delta.content === 'string') inBandReasoning.push(delta.content)\n\n        if (opts.visibleOnly) {\n          if (typeof delta.content === 'string') {\n            const chunk = visible.push(delta.content)\n            if (chunk) { transport.output('visibleEvents'); opts.onChunk(chunk) }\n          }\n          return\n        }\n\n        let emitChunk = ''\n        if (delta.reasoning_content) {\n          if (!isThinking) {\n            isThinking = true\n            emitChunk += '<think>\\n'\n          }\n          emitChunk += delta.reasoning_content\n        }\n        if (delta.content !== undefined && delta.content !== null) {\n          if (isThinking) {\n            isThinking = false\n            emitChunk += '\\n</think>\\n\\n'\n          }\n          emitChunk += delta.content\n        }\n        if (emitChunk) {\n          if (delta.content) transport.output('visibleEvents')\n          fullText += emitChunk\n          opts.onChunk(emitChunk)\n        }\n      }\n\n      const processLine = (line: string) => {\n        if (line === '') {\n          if (dataLines.length > 0) processEvent(dataLines.join('\\n'))\n          dataLines = []\n          return\n        }\n        if (line.startsWith(':')) return\n        const colon = line.indexOf(':')\n        const field = colon === -1 ? line : line.slice(0, colon)\n        if (field !== 'data') return\n        let value = colon === -1 ? '' : line.slice(colon + 1)\n        if (value.startsWith(' ')) value = value.slice(1)\n        dataLines.push(value)\n      }\n\n      const processText = (text: string, final = false) => {\n        lineBuffer += text\n        let consumed = 0\n        for (let index = 0; index < lineBuffer.length;) {\n          const character = lineBuffer[index]\n          if (character !== '\\r' && character !== '\\n') {\n            index += 1\n            continue\n          }\n          if (character === '\\r' && index + 1 === lineBuffer.length && !final) break\n          processLine(lineBuffer.slice(consumed, index))\n          index += character === '\\r' && lineBuffer[index + 1] === '\\n' ? 2 : 1\n          consumed = index\n          if (fatalError || sawDone) break\n        }\n        lineBuffer = lineBuffer.slice(consumed)\n        if (final && !fatalError && !sawDone) {\n          if (lineBuffer) processLine(lineBuffer)\n          lineBuffer = ''\n          processLine('')\n        }\n      }\n\n      while (!fatalError && !sawDone) {\n        const { done, value } = await transport.read(reader)\n        if (done) break\n        processText(decoder.decode(value, { stream: true }))\n      }\n\n      if (!fatalError && !sawDone) {\n        processText(decoder.decode(), true)\n      }\n\n      if (fatalError) {\n        transport.errorCode(fatalError === 'LLM_STREAM_PROVIDER_ERROR' ? 'PROVIDER_STREAM_ERROR' : 'STREAM_INVALID')\n        protocolError = fatalError\n        throw new Error(fatalError)\n      }\n\n      if (!sawDone) {\n        transport.errorCode('STREAM_INCOMPLETE')\n        protocolError = 'LLM_STREAM_INCOMPLETE'\n        throw new Error(protocolError)\n      }\n\n      if (isThinking) {\n        const closeTag = '\\n</think>\\n\\n'\n        opts.onChunk(closeTag)\n        fullText += closeTag\n      }\n\n      transport.completed()\n      opts.onDone(opts.visibleOnly ? visible.text : this.stripThinking(fullText), usage, finishReason)\n    } catch (error) {\n      transport.interrupted(error, opts.signal.aborted)\n      if (opts.signal.aborted) {\n        fail('LLM_CANCELLED')\n      } else {\n        fail(protocolError ?? (transport.networkFailure ? 'LLM_STREAM_NETWORK_FAILED' : 'LLM_STREAM_FAILED'))\n      }\n    } finally {\n      // Do not wait for a remote stream to settle before releasing the local task.\n      void reader?.cancel?.().catch(() => {})\n      reader?.releaseLock?.()\n    }\n  }\n}\n"
    },
    {
      "path": "electron/repositories/finalization-repository.ts",
      "content": "import { createHash } from 'node:crypto'\nimport { getCurrentProjectPath, getProjectDb } from '../database'\nimport { readPortableRuntimeFreeze } from '../services/portable-runtime-freeze'\nimport { countDraftUnits } from '../../src/shared/draft-units'\nimport type { DuplicateFinalizationRepair, RepairedDuplicateChapter } from '../../src/shared/finalization-repair'\nimport type { ReopenChapterRequest, ReopenChapterResult, ReopenedFinal } from '../../src/shared/chapter-reopen'\nimport type { ReplacedFinalCleanupStepKey } from '../../src/shared/finalization-step-error'\nimport { DraftRepository } from './draft-repository'\nimport { NarrativeThreadRepository } from './narrative-thread-repository'\nimport { PostProcessRepository } from './post-process-repository'\nimport { freezeFinalizedCharacterSnapshot, invalidateContinuityProjectionFrom } from './summary-repository'\n\nexport type PublicationStatus = 'pending' | 'published'\n\nexport interface FinalizationCommitInput {\n  finalizationId: string\n  draftId: number\n  chapterNumber: number\n  chapterTitle: string\n  content: string\n  contentHash: string\n  contentRevision: number\n  targetFileName: string\n}\n\nexport interface FinalizationRecord {\n  finalizationId: string\n  draftId: number\n  chapterNumber: number\n  chapterTitle: string\n  /** outbox 内冻结的不可变正文；发布和重试绝不回读 contents.body。 */\n  contentSnapshot: string\n  contentHash: string\n  contentRevision: number\n  targetFileName: string\n  knowledgeDocumentId: string\n  publicationStatus: PublicationStatus\n  lastError: string\n  publishedAt: string | null\n}\n\ninterface FinalizationRow {\n  finalization_id: string\n  draft_id: number\n  chapter_number: number\n  chapter_title: string\n  content_hash: string\n  content_revision: number\n  target_file_name: string\n  knowledge_document_id: string\n  publication_status: PublicationStatus\n  last_error: string\n  published_at: string | null\n  content_snapshot: string\n}\n\nexport interface FinalizedDraftExportSnapshot {\n  draftId: number\n  chapterNumber: number\n  version: number\n  title: string\n  content: string\n  finalizationId: string | null\n  contentHash: string\n}\n\nexport type FinalizedDraftExportAuthorityReceipt = ReadonlyArray<Readonly<{\n  draftId: number\n  chapterNumber: number\n  version: number\n  finalizationId: string | null\n  contentHash: string\n}>>\n\ninterface FinalizedDraftExportRow {\n  draft_id: number\n  chapter_number: number\n  version: number\n  body: string\n  finalization_id: string | null\n  outbox_chapter_number: number | null\n  chapter_title: string | null\n  content_hash: string | null\n  content_snapshot: string | null\n}\n\ninterface AuthoritativeFinalizedDraftExport {\n  snapshot: FinalizedDraftExportSnapshot\n  receipt: FinalizedDraftExportAuthorityReceipt[number]\n}\n\nfunction rowToRecord(row: FinalizationRow): FinalizationRecord {\n  return {\n    finalizationId: row.finalization_id,\n    draftId: row.draft_id,\n    chapterNumber: row.chapter_number,\n    chapterTitle: row.chapter_title,\n    contentSnapshot: row.content_snapshot ?? '',\n    contentHash: row.content_hash,\n    contentRevision: row.content_revision,\n    targetFileName: row.target_file_name,\n    knowledgeDocumentId: row.knowledge_document_id ?? '',\n    publicationStatus: row.publication_status,\n    lastError: row.last_error ?? '',\n    publishedAt: row.published_at ?? null,\n  }\n}\n\nfunction sha256(value: string): string {\n  return createHash('sha256').update(value, 'utf8').digest('hex')\n}\n\nfunction requireDatabase() {\n  const db = getProjectDb()\n  if (!db) throw new Error('PROJECT_NOT_OPEN')\n  return db\n}\n\ntype Db = ReturnType<typeof requireDatabase>\n\nfunction hasSameFinalizationInput(\n  existing: FinalizationRow,\n  input: FinalizationCommitInput,\n): boolean {\n  return existing.draft_id === input.draftId\n    && existing.chapter_number === input.chapterNumber\n    && existing.chapter_title === input.chapterTitle\n    && existing.content_hash === input.contentHash\n    && existing.content_revision === input.contentRevision\n    && existing.content_snapshot === input.content\n}\n\nfunction selectAuthoritativeExportRows(\n  rows: readonly FinalizedDraftExportRow[],\n): AuthoritativeFinalizedDraftExport[] {\n  const selected: AuthoritativeFinalizedDraftExport[] = []\n  const selectedVersions = new Map<number, number>()\n  for (const row of rows) {\n    const selectedVersion = selectedVersions.get(row.chapter_number)\n    if (selectedVersion !== undefined) {\n      if (selectedVersion === row.version) {\n        throw new Error('FINALIZATION_EXPORT_DUPLICATE_CHAPTER')\n      }\n      continue\n    }\n    if (\n      !Number.isSafeInteger(row.draft_id) || row.draft_id < 1\n      || !Number.isSafeInteger(row.chapter_number) || row.chapter_number < 1\n      || !Number.isSafeInteger(row.version) || row.version < 1\n    ) throw new Error('FINALIZATION_EXPORT_SNAPSHOT_INVALID')\n    if (typeof row.body !== 'string' || row.body.trim().length === 0) {\n      throw new Error('FINALIZATION_EXPORT_CONTENT_EMPTY')\n    }\n\n    const contentHash = sha256(row.body)\n    if (row.finalization_id !== null) {\n      if (typeof row.finalization_id !== 'string' || row.finalization_id.trim().length === 0) {\n        throw new Error('FINALIZATION_EXPORT_SNAPSHOT_INVALID')\n      }\n      if (row.outbox_chapter_number !== row.chapter_number) {\n        throw new Error('FINALIZATION_EXPORT_IDENTITY_MISMATCH')\n      }\n      if (row.content_snapshot !== row.body) {\n        throw new Error('FINALIZATION_EXPORT_CONTENT_MISMATCH')\n      }\n      if (row.content_hash !== contentHash) {\n        throw new Error('FINALIZATION_EXPORT_SUMMARY_MISMATCH')\n      }\n    }\n\n    selectedVersions.set(row.chapter_number, row.version)\n    const authority = {\n      draftId: row.draft_id,\n      chapterNumber: row.chapter_number,\n      version: row.version,\n      finalizationId: row.finalization_id,\n      contentHash,\n    }\n    selected.push({\n      receipt: authority,\n      snapshot: {\n        ...authority,\n        title: row.chapter_title?.trim() ?? '',\n        content: row.body,\n      },\n    })\n  }\n  return selected\n}\n\nconst AUTHORITATIVE_FINALIZED_ORDER = 'drafts.chapter_number ASC, drafts.version DESC, drafts.id DESC'\n\nfunction readAuthoritativeExportRows(): AuthoritativeFinalizedDraftExport[] {\n  const db = requireDatabase()\n  return db.transaction(() => selectAuthoritativeExportRows(db.prepare(`\n    SELECT drafts.id AS draft_id, drafts.chapter_number, drafts.version,\n           contents.body, finalization_outbox.finalization_id,\n           finalization_outbox.chapter_number AS outbox_chapter_number,\n           finalization_outbox.chapter_title, finalization_outbox.content_hash,\n           finalization_outbox.content_snapshot\n    FROM drafts\n    JOIN contents ON contents.id = drafts.content_id\n    LEFT JOIN finalization_outbox ON finalization_outbox.draft_id = drafts.id\n    WHERE drafts.status = 'finalized'\n    ORDER BY ${AUTHORITATIVE_FINALIZED_ORDER}\n  `).all() as FinalizedDraftExportRow[]))()\n}\n\n/**\n * 定稿的数据库事实源。正文、字数、定稿状态与发布 outbox 必须由同一个 SQLite\n * transaction 共同提交；任何一个 statement 失败都会回滚其余变化。\n */\nexport class FinalizationRepository {\n  /** One transactionally frozen, highest-version finalized fact per chapter. */\n  static listAuthoritativeForExport(): FinalizedDraftExportSnapshot[] {\n    return readAuthoritativeExportRows().map(({ snapshot }) => snapshot)\n  }\n\n  static matchesAuthoritativeExportReceipt(receipt: FinalizedDraftExportAuthorityReceipt): boolean {\n    if (!Array.isArray(receipt)) return false\n    const seenChapters = new Set<number>()\n    for (const item of receipt) {\n      if (\n        !item || typeof item !== 'object'\n        || !Number.isSafeInteger(item.draftId) || item.draftId < 1\n        || !Number.isSafeInteger(item.chapterNumber) || item.chapterNumber < 1\n        || !Number.isSafeInteger(item.version) || item.version < 1\n        || !(item.finalizationId === null\n          || (typeof item.finalizationId === 'string' && item.finalizationId.trim().length > 0))\n        || typeof item.contentHash !== 'string' || !/^[a-f0-9]{64}$/u.test(item.contentHash)\n        || seenChapters.has(item.chapterNumber)\n      ) return false\n      seenChapters.add(item.chapterNumber)\n    }\n\n    try {\n      const current = readAuthoritativeExportRows().map(({ receipt: item }) => item)\n      return current.length === receipt.length && current.every((item, index) => (\n        item.draftId === receipt[index]?.draftId\n        && item.chapterNumber === receipt[index]?.chapterNumber\n        && item.version === receipt[index]?.version\n        && item.finalizationId === receipt[index]?.finalizationId\n        && item.contentHash === receipt[index]?.contentHash\n      ))\n    } catch {\n      return false\n    }\n  }\n\n  static commit(input: FinalizationCommitInput): FinalizationRecord {\n    const db = requireDatabase()\n    const transaction = db.transaction(() => {\n      const existing = db.prepare(`\n        SELECT * FROM finalization_outbox WHERE draft_id = ?\n      `).get(input.draftId) as FinalizationRow | undefined\n      if (existing) {\n        // renderer 可能在主进程已提交而响应丢失后重发同一冻结快照。此时新生成的\n        // finalizationId/碰撞候选文件名都不能破坏幂等性，必须返回原提交。\n        if (hasSameFinalizationInput(existing, input)) {\n          return rowToRecord(existing)\n        }\n        throw new Error('FINALIZATION_COMMIT_CONFLICT')\n      }\n\n      const draft = db.prepare(`\n        SELECT id, chapter_number, status, content_id FROM drafts WHERE id = ?\n      `).get(input.draftId) as {\n        id: number\n        chapter_number: number\n        status: string\n        content_id: number\n      } | undefined\n      if (!draft) throw new Error('DRAFT_NOT_FOUND')\n      if (draft.chapter_number !== input.chapterNumber) {\n        throw new Error('FINALIZATION_COMMIT_CHAPTER_MISMATCH')\n      }\n      if (draft.status === 'finalized') {\n        throw new Error('FINALIZATION_COMMIT_OUTBOX_MISSING')\n      }\n      if (draft.status === 'superseded') {\n        throw new Error('FINALIZATION_COMMIT_SUPERSEDED')\n      }\n\n      const replacedDraftIds = (db.prepare(`\n        SELECT id FROM drafts WHERE chapter_number = ? AND status = 'finalized' AND id <> ?\n      `).all(input.chapterNumber, input.draftId) as { id: number }[]).map(row => row.id)\n      if (replacedDraftIds.length > 0 && DraftRepository.findOpenReopenDraft(input.chapterNumber, db)?.id !== input.draftId) {\n        throw new Error('CHAPTER_FINALIZED_REOPEN_REQUIRED')\n      }\n      FinalizationRepository.demoteToSuperseded(db, replacedDraftIds)\n\n      db.prepare('UPDATE contents SET body = ? WHERE id = ?')\n        .run(input.content, draft.content_id)\n      db.prepare(`\n        UPDATE drafts_all\n        SET status = 'finalized', word_count = ?, updated_at = datetime('now')\n        WHERE id = ?\n      `).run(countDraftUnits(input.content), input.draftId)\n      db.prepare(`\n        INSERT INTO finalization_outbox_all (\n          finalization_id, draft_id, chapter_number, chapter_title,\n          content_hash, content_revision, content_snapshot, target_file_name, publication_status,\n          last_error\n        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending', '')\n      `).run(\n        input.finalizationId,\n        input.draftId,\n        input.chapterNumber,\n        input.chapterTitle,\n        input.contentHash,\n        input.contentRevision,\n        input.content,\n        input.targetFileName,\n      )\n      freezeFinalizedCharacterSnapshot(db, { draftId: input.draftId, finalizationId: input.finalizationId,\n        chapterNumber: input.chapterNumber, contentHash: input.contentHash })\n      NarrativeThreadRepository.carryConfirmationsToReplacement(replacedDraftIds,\n        { draftId: input.draftId, content: input.content }, db)\n\n      return {\n        finalizationId: input.finalizationId,\n        draftId: input.draftId,\n        chapterNumber: input.chapterNumber,\n        chapterTitle: input.chapterTitle,\n        contentSnapshot: input.content,\n        contentHash: input.contentHash,\n        contentRevision: input.contentRevision,\n        targetFileName: input.targetFileName,\n        knowledgeDocumentId: '',\n        publicationStatus: 'pending' as const,\n        lastError: '',\n        publishedAt: null,\n      }\n    })\n    return transaction()\n  }\n\n  static reopen(request: ReopenChapterRequest): ReopenChapterResult {\n    if (!Number.isSafeInteger(request?.chapterNumber) || request.chapterNumber < 1\n      || (request.initialDraftId !== undefined && (!Number.isSafeInteger(request.initialDraftId) || request.initialDraftId < 1))) {\n      throw new Error('CHAPTER_REOPEN_REQUEST_INVALID')\n    }\n    const db = requireDatabase()\n    return db.transaction((): ReopenChapterResult => {\n      const base = db.prepare(`\n        SELECT drafts.id, contents.body, finalization_outbox.finalization_id,\n               finalization_outbox.content_hash, finalization_outbox.content_snapshot\n        FROM drafts\n        JOIN contents ON contents.id = drafts.content_id\n        LEFT JOIN finalization_outbox ON finalization_outbox.draft_id = drafts.id\n        WHERE drafts.chapter_number = ? AND drafts.status = 'finalized'\n        ORDER BY ${AUTHORITATIVE_FINALIZED_ORDER}\n        LIMIT 1\n      `).get(request.chapterNumber) as {\n        id: number\n        body: string\n        finalization_id: string | null\n        content_hash: string | null\n        content_snapshot: string | null\n      } | undefined\n      if (!base) throw new Error('CHAPTER_REOPEN_NOT_FINALIZED')\n      const contentHash = sha256(base.body)\n      if (base.finalization_id !== null && (base.content_snapshot !== base.body || base.content_hash !== contentHash)) {\n        throw new Error('FINALIZATION_SNAPSHOT_HASH_MISMATCH')\n      }\n      const bodyOf = db.prepare(`\n        SELECT contents.body FROM drafts JOIN contents ON contents.id = drafts.content_id\n        WHERE drafts.id = ? AND drafts.chapter_number = ?\n      `).pluck()\n      const initial = request.initialDraftId === undefined\n        ? base.body\n        : bodyOf.get(request.initialDraftId, request.chapterNumber) as string | undefined\n      if (initial === undefined) throw new Error('CHAPTER_REOPEN_VERSION_INVALID')\n\n      const open = DraftRepository.findOpenReopenDraft(request.chapterNumber, db)\n      if (open) {\n        if (request.initialDraftId !== undefined && bodyOf.get(open.id, request.chapterNumber) !== initial) {\n          throw new Error('CHAPTER_REOPEN_ALREADY_OPEN')\n        }\n        return { success: true, created: false, draftId: open.id, version: open.version }\n      }\n      const reopened: ReopenedFinal = base.finalization_id === null\n        ? { kind: 'legacy-finalized', draftId: base.id, chapterNumber: request.chapterNumber, contentHash }\n        : { kind: 'finalized', draftId: base.id, chapterNumber: request.chapterNumber, finalizationId: base.finalization_id, contentHash }\n      const draftId = DraftRepository.create({\n        chapterNumber: request.chapterNumber,\n        source: 'rewrite',\n        content: initial,\n        wordCount: countDraftUnits(initial),\n        sourceDependencies: [reopened],\n      }, db)\n      const version = db.prepare('SELECT version FROM drafts WHERE id = ?').pluck().get(draftId) as number\n      return { success: true, created: true, draftId, version }\n    }).immediate()\n  }\n\n  static repairDuplicateFinalizations(cleanupLabels: Readonly<Record<ReplacedFinalCleanupStepKey, string>>): DuplicateFinalizationRepair {\n    const db = requireDatabase()\n    return db.transaction(() => {\n      const rows = db.prepare(`\n        SELECT drafts.id, drafts.chapter_number, drafts.version,\n               finalization_outbox.knowledge_document_id, finalization_outbox.target_file_name,\n               finalization_outbox.publication_status\n        FROM drafts\n        LEFT JOIN finalization_outbox ON finalization_outbox.draft_id = drafts.id\n        WHERE drafts.status = 'finalized' AND drafts.chapter_number IN (\n          SELECT chapter_number FROM drafts WHERE status = 'finalized'\n          GROUP BY chapter_number HAVING COUNT(*) > 1\n        )\n        ORDER BY ${AUTHORITATIVE_FINALIZED_ORDER}\n      `).all() as Array<{\n        id: number\n        chapter_number: number\n        version: number\n        knowledge_document_id: string | null\n        target_file_name: string | null\n        publication_status: string | null\n      }>\n      const chapters: RepairedDuplicateChapter[] = []\n      let keptFileName = ''\n      for (const row of rows) {\n        const current = chapters.at(-1)\n        if (current?.chapterNumber !== row.chapter_number) {\n          chapters.push({ chapterNumber: row.chapter_number, keptDraftId: row.id, keptVersion: row.version, superseded: [], cleanupRegistered: false })\n          keptFileName = row.target_file_name ?? ''\n          continue\n        }\n        FinalizationRepository.demoteToSuperseded(db, [row.id])\n        current.superseded.push({\n          draftId: row.id,\n          version: row.version,\n          knowledgeDocumentId: row.knowledge_document_id ?? '',\n          targetFileName: row.publication_status === 'published' && row.target_file_name !== keptFileName\n            ? row.target_file_name ?? '' : '',\n        })\n      }\n      for (const chapter of chapters) {\n        const cleanup: ReplacedFinalCleanupStepKey[] = [\n          ...chapter.superseded.some(item => item.knowledgeDocumentId) ? ['remove_replaced_knowledge' as const] : [],\n          ...chapter.superseded.some(item => item.targetFileName) ? ['remove_replaced_manuscripts' as const] : [],\n        ]\n        const run = PostProcessRepository.getLatestRun('chapter_finalize', String(chapter.chapterNumber))\n        if (cleanup.length === 0 || !run?.triggerSourceId.startsWith('finalization:')) continue\n        PostProcessRepository.addUnfinishedSteps(run.id, cleanup.map(key => ({ key, label: cleanupLabels[key], critical: false })),\n          'FINALIZATION_REPLACED_CLEANUP_PENDING')\n        chapter.cleanupRegistered = true\n      }\n      if (chapters.length > 0) invalidateContinuityProjectionFrom(db, chapters[0]!.chapterNumber)\n      return { chapters }\n    }).immediate()\n  }\n\n  /**\n   * finalized 与 superseded 只由本模块写（ADR-0003、ADR-0025）。定稿或回收站里的行降为只读的被替换定稿；\n   * 回收站里的行同时清掉删除三列（M07 触发器要求它们与状态同进退）。\n   */\n  static demoteToSuperseded(db: Db, draftIds: readonly number[]): void {\n    const demote = db.prepare(`\n      UPDATE drafts_all SET status = 'superseded', deletion_id = '', deleted_from_status = '', deleted_at = '',\n        updated_at = datetime('now')\n      WHERE id = ? AND status IN ('finalized', 'deleted')\n    `)\n    for (const id of draftIds) {\n      if (demote.run(id).changes !== 1) throw new Error('FINALIZATION_DEMOTE_TARGET_INVALID')\n    }\n  }\n\n  /**\n   * 回收站里一次删除的各行回到 live，调用方持有事务。into-gap 按删前状态翻回，主定稿的实体稿置为待发布\n   * （删除时已移除，可换不撞名的目标）；as-history 一律降为被替换的旧定稿。知识文档在删除时已清掉，\n   * 未冻结的收据把知识文档 ID 置空，等 kb_import 回链。\n   */\n  static reinstateDeleted(db: Db, deletion: { deletionId: string; chapterNumber: number } & (\n    | { as: 'original'; republish: { finalizationId: string; targetFileName: string } }\n    | { as: 'superseded' }\n  )): void {\n    const rows = db.prepare(`\n      SELECT d.id, o.finalization_id FROM drafts_all d LEFT JOIN finalization_outbox_all o ON o.draft_id = d.id\n      WHERE d.deletion_id = ? AND d.status = 'deleted' AND d.chapter_number = ?\n    `).all(deletion.deletionId, deletion.chapterNumber) as Array<{ id: number; finalization_id: string | null }>\n    if (rows.length === 0) throw new Error('FINALIZATION_REINSTATE_TARGET_INVALID')\n    const liveFinal = () => db.prepare(`SELECT COUNT(*) FROM drafts WHERE chapter_number = ? AND status = 'finalized'`)\n      .pluck().get(deletion.chapterNumber) as number\n    if (deletion.as === 'superseded') {\n      FinalizationRepository.demoteToSuperseded(db, rows.map(row => row.id))\n    } else {\n      if (liveFinal() !== 0) throw new Error('FINALIZATION_REINSTATE_CHAPTER_FINALIZED')\n      db.prepare(`\n        UPDATE drafts_all SET status = deleted_from_status, deletion_id = '', deleted_from_status = '', deleted_at = '',\n          updated_at = datetime('now')\n        WHERE deletion_id = ? AND status = 'deleted' AND chapter_number = ?\n      `).run(deletion.deletionId, deletion.chapterNumber)\n      if (liveFinal() !== 1) throw new Error('FINALIZATION_REINSTATE_TARGET_INVALID')\n    }\n    const freeze = readPortableRuntimeFreeze(getCurrentProjectPath())\n    const forget = db.prepare(`UPDATE finalization_outbox_all SET knowledge_document_id = '', updated_at = datetime('now') WHERE finalization_id = ?`)\n    for (const row of rows) {\n      if (row.finalization_id && !freeze.isFrozen('finalization_outbox', row.finalization_id)) forget.run(row.finalization_id)\n    }\n    if (deletion.as === 'original') {\n      freeze.assertMutable('finalization_outbox', deletion.republish.finalizationId)\n      const updated = db.prepare(`\n        UPDATE finalization_outbox_all\n        SET publication_status = 'pending', last_error = '', published_at = NULL, target_file_name = ?, updated_at = datetime('now')\n        WHERE finalization_id = ? AND draft_id IN (SELECT id FROM drafts WHERE status = 'finalized' AND chapter_number = ?)\n      `).run(deletion.republish.targetFileName, deletion.republish.finalizationId, deletion.chapterNumber)\n      if (updated.changes !== 1) throw new Error('FINALIZATION_REINSTATE_TARGET_INVALID')\n    }\n  }\n\n  static isAuthoritative(draftId: number): boolean {\n    return requireDatabase().prepare(`\n      SELECT drafts.id FROM drafts\n      WHERE drafts.status = 'finalized'\n        AND drafts.chapter_number = (SELECT chapter_number FROM drafts WHERE id = ?)\n      ORDER BY ${AUTHORITATIVE_FINALIZED_ORDER}\n      LIMIT 1\n    `).pluck().get(draftId) === draftId\n  }\n\n  static get(finalizationId: string): FinalizationRecord | null {\n    const db = requireDatabase()\n    const row = db.prepare(`\n      SELECT * FROM finalization_outbox WHERE finalization_id = ?\n    `).get(finalizationId) as FinalizationRow | undefined\n    return row ? rowToRecord(row) : null\n  }\n\n  /** 定稿收进知识库的文档身份到章号；知识库凭它区分定稿章节与作者导入的资料（两者都写项目副本）。 */\n  static knowledgeDocumentChapters(): Map<string, number> {\n    const rows = requireDatabase().prepare(`\n      SELECT knowledge_document_id, chapter_number FROM finalization_outbox WHERE knowledge_document_id != ''\n    `).all() as Array<{ knowledge_document_id: string; chapter_number: number }>\n    return new Map(rows.map(row => [row.knowledge_document_id, row.chapter_number]))\n  }\n\n  static getByDraftId(draftId: number): FinalizationRecord | null {\n    const db = requireDatabase()\n    const row = db.prepare(`\n      SELECT * FROM finalization_outbox WHERE draft_id = ?\n    `).get(draftId) as FinalizationRow | undefined\n    return row ? rowToRecord(row) : null\n  }\n\n  static linkKnowledgeDocument(draftId: number, documentId: string): FinalizationRecord {\n    const normalizedDocumentId = documentId.trim()\n    if (!normalizedDocumentId) throw new Error('FINALIZATION_COMMIT_KNOWLEDGE_DOCUMENT_REQUIRED')\n    const db = requireDatabase()\n    const existing = db.prepare(`\n      SELECT finalization_id FROM finalization_outbox WHERE draft_id = ?\n    `).get(draftId) as { finalization_id: string } | undefined\n    if (!existing) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    readPortableRuntimeFreeze(getCurrentProjectPath()).assertMutable('finalization_outbox', existing.finalization_id)\n    const result = db.prepare(`\n      UPDATE finalization_outbox_all\n      SET knowledge_document_id = ?, updated_at = datetime('now')\n      WHERE draft_id = ? AND finalization_id = ?\n    `).run(normalizedDocumentId, draftId, existing.finalization_id)\n    if (result.changes !== 1) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    const record = FinalizationRepository.getByDraftId(draftId)\n    if (!record) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    return record\n  }\n\n  static markPublicationPending(finalizationId: string, error: string): FinalizationRecord {\n    const db = requireDatabase()\n    const result = db.prepare(`\n      UPDATE finalization_outbox_all\n      SET publication_status = 'pending', last_error = ?, updated_at = datetime('now')\n      WHERE finalization_id = ?\n    `).run(error, finalizationId)\n    if (result.changes !== 1) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    const record = FinalizationRepository.get(finalizationId)\n    if (!record) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    return record\n  }\n\n  static markPublished(finalizationId: string): FinalizationRecord {\n    const db = requireDatabase()\n    const result = db.prepare(`\n      UPDATE finalization_outbox_all\n      SET publication_status = 'published', last_error = '',\n          published_at = datetime('now'), updated_at = datetime('now')\n      WHERE finalization_id = ?\n    `).run(finalizationId)\n    if (result.changes !== 1) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    const record = FinalizationRepository.get(finalizationId)\n    if (!record) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    return record\n  }\n}\n"
    },
    {
      "path": "electron/repositories/revision-repository.ts",
      "content": "/**\n * RevisionRepository — 修稿 (revisions 表 + contents 联动)\n *\n * 修稿是基于某一版草稿的探索分支。\n * 状态流转：pending → merged / discarded\n */\nimport { createHash } from 'node:crypto'\nimport { getProjectDb } from '../database'\nimport { ContentRepository } from './content-repository'\nimport { ReviewCycleRepository } from './review-cycle-repository'\nimport type { ExpectedDraftSource } from '../../src/shared/ipc-channels'\nimport { assertExpectedDraftSource, LIVE_PARENT, SourceDraftChangedError } from './draft-source-guard'\n\nconst contentHash = (value: string) => createHash('sha256').update(value).digest('hex')\nconst hasReviewCycleSchema = (db: import('better-sqlite3').Database) => Boolean(\n    db.prepare(\"SELECT 1 FROM sqlite_master WHERE type='table' AND name='review_cycles'\").get()\n)\n\n/** 修稿元数据（不含正文） */\nexport interface RevisionMeta {\n    id: number\n    baseDraftId: number\n    revisionIndex: number\n    revisionType: string\n    status: string\n    mergedToDraftId: number | null\n    userPrompt: string\n    reviewSourceId: number | null\n    contentId: number\n    wordCount: number\n    createdAt: string\n    updatedAt: string\n}\n\n/** 修稿完整数据（含正文） */\nexport interface RevisionFull extends RevisionMeta {\n    content: string\n    sourceDraft: ExpectedDraftSource | null\n}\n\nexport interface MergeRevisionRequest {\n    revisionId: number\n    targetDraftId: number\n    expectedDraftContent: string\n    mergedContent: string\n    wordCount: number\n}\n\nexport interface MergeRevisionReceipt {\n    revisionId: number\n    targetDraftId: number\n    status: 'revised'\n    wordCount: number\n    idempotent: boolean\n    chapterNumber: number\n    version: number\n    reviewCycle?: {\n        cycleId: string\n        mergedHash: string\n        disposition: 'required' | 'not-required' | 'completed'\n    }\n}\n\nfunction rowToSourceDraft(row: Record<string, unknown>): ExpectedDraftSource | null {\n    if (\n        typeof row.source_draft_chapter_number !== 'number'\n        || typeof row.source_draft_version !== 'number'\n        || typeof row.source_draft_status !== 'string'\n        || typeof row.source_content !== 'string'\n    ) return null\n    return {\n        id: row.base_draft_id as number,\n        chapterNumber: row.source_draft_chapter_number,\n        version: row.source_draft_version,\n        status: row.source_draft_status as ExpectedDraftSource['status'],\n        content: row.source_content,\n    }\n}\n\nfunction rowToMeta(row: Record<string, unknown>): RevisionMeta {\n    return {\n        id: row.id as number,\n        baseDraftId: row.base_draft_id as number,\n        revisionIndex: row.revision_index as number,\n        revisionType: row.revision_type as string,\n        status: row.status as string,\n        mergedToDraftId: (row.merged_to_draft_id as number | null) ?? null,\n        userPrompt: (row.user_prompt as string) ?? '',\n        reviewSourceId: (row.review_source_id as number | null) ?? null,\n        contentId: row.content_id as number,\n        wordCount: row.word_count as number,\n        createdAt: row.created_at as string,\n        updatedAt: row.updated_at as string,\n    }\n}\n\nexport class RevisionRepository {\n    /**\n     * 创建修稿（事务内原子分配 revision_index，再入内容池 + 元数据）\n     * 不接受调用方传入序号，避免与落库结果不一致。\n     */\n    static create(params: {\n        baseDraftId: number\n        revisionType: 'refine' | 'review-fix'\n        userPrompt?: string\n        reviewSourceId?: number\n        content: string\n        wordCount: number\n        expectedSource?: ExpectedDraftSource\n    }): { id: number; revisionIndex: number } {\n        const db = getProjectDb()\n        if (!db) throw new Error('PROJECT_NOT_OPEN')\n\n        const tx = db.transaction(() => {\n            if (!params.expectedSource) throw new SourceDraftChangedError()\n            assertExpectedDraftSource(db, params.baseDraftId, params.expectedSource)\n            const row = db.prepare(`\n        SELECT MAX(revision_index) as maxIdx FROM revisions WHERE base_draft_id = ?\n      `).get(params.baseDraftId) as { maxIdx: number | null }\n            const revisionIndex = (row.maxIdx ?? 0) + 1\n\n            const contentId = ContentRepository.create(params.content)\n            const result = db.prepare(`\n        INSERT INTO revisions (\n          base_draft_id, revision_index, revision_type,\n          user_prompt, review_source_id,\n          source_draft_chapter_number, source_draft_version, source_draft_status, source_content,\n          content_id, word_count\n        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n      `).run(\n                params.baseDraftId,\n                revisionIndex,\n                params.revisionType,\n                params.userPrompt ?? '',\n                params.reviewSourceId ?? null,\n                params.expectedSource?.chapterNumber ?? null,\n                params.expectedSource?.version ?? null,\n                params.expectedSource?.status ?? null,\n                params.expectedSource?.content ?? null,\n                contentId,\n                params.wordCount,\n            )\n            return { id: Number(result.lastInsertRowid), revisionIndex }\n        })\n\n        return tx()\n    }\n\n    /**\n     * 原子替换同一草稿的 pending 修稿：新修稿创建失败时，旧 pending\n     * 状态与内容池分配会随整个 SQLite 事务一起回滚。\n     */\n    static replacePending(params: {\n        baseDraftId: number\n        revisionType: 'refine' | 'review-fix'\n        userPrompt?: string\n        reviewSourceId?: number\n        content: string\n        wordCount: number\n        expectedSource?: ExpectedDraftSource\n    }, db = getProjectDb()): { id: number; revisionIndex: number; discardedRevisionIds: number[] } {\n        if (!db) throw new Error('PROJECT_NOT_OPEN')\n\n        return db.transaction(() => {\n            if (!params.expectedSource) throw new SourceDraftChangedError()\n            assertExpectedDraftSource(db, params.baseDraftId, params.expectedSource)\n            const row = db.prepare(`\n        SELECT MAX(revision_index) as maxIdx FROM revisions WHERE base_draft_id = ?\n      `).get(params.baseDraftId) as { maxIdx: number | null }\n            const revisionIndex = (row.maxIdx ?? 0) + 1\n            const contentId = ContentRepository.create(params.content, db)\n            const result = db.prepare(`\n        INSERT INTO revisions (\n          base_draft_id, revision_index, revision_type,\n          user_prompt, review_source_id,\n          source_draft_chapter_number, source_draft_version, source_draft_status, source_content,\n          content_id, word_count\n        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n      `).run(\n                params.baseDraftId,\n                revisionIndex,\n                params.revisionType,\n                params.userPrompt ?? '',\n                params.reviewSourceId ?? null,\n                params.expectedSource?.chapterNumber ?? null,\n                params.expectedSource?.version ?? null,\n                params.expectedSource?.status ?? null,\n                params.expectedSource?.content ?? null,\n                contentId,\n                params.wordCount,\n            )\n            const id = Number(result.lastInsertRowid)\n            const discardedRevisionIds = (db.prepare(`\n        SELECT id FROM revisions\n        WHERE base_draft_id = ? AND status = 'pending' AND id <> ?\n        ORDER BY id\n      `).all(params.baseDraftId, id) as Array<{ id: number }>).map(row => row.id)\n            db.prepare(`\n        UPDATE revisions SET status = 'discarded', updated_at = datetime('now')\n        WHERE base_draft_id = ? AND status = 'pending' AND id <> ?\n      `).run(params.baseDraftId, id)\n            if (hasReviewCycleSchema(db)) {\n                ReviewCycleRepository.reconcileDiscardedRevisions(discardedRevisionIds, db)\n            }\n            return { id, revisionIndex, discardedRevisionIds }\n        })()\n    }\n\n    /** 列出某草稿的所有修稿 */\n    static listByDraft(baseDraftId: number): RevisionMeta[] {\n        const db = getProjectDb()\n        if (!db) return []\n\n        const rows = db.prepare(`\n      SELECT * FROM revisions\n      WHERE base_draft_id = ? AND ${LIVE_PARENT}\n      ORDER BY revision_index ASC\n    `).all(baseDraftId) as Record<string, unknown>[]\n\n        return rows.map(rowToMeta)\n    }\n\n    /** 获取某草稿的所有 pending 修稿 */\n    static getPending(baseDraftId: number): RevisionMeta[] {\n        const db = getProjectDb()\n        if (!db) return []\n\n        const rows = db.prepare(`\n      SELECT * FROM revisions\n      WHERE base_draft_id = ? AND status = 'pending' AND ${LIVE_PARENT}\n      ORDER BY revision_index ASC\n    `).all(baseDraftId) as Record<string, unknown>[]\n\n        return rows.map(rowToMeta)\n    }\n\n    /** 获取修稿完整数据 */\n    static getFull(id: number, db = getProjectDb()): RevisionFull | null {\n        if (!db) return null\n\n        const row = db.prepare(\n            `SELECT * FROM revisions WHERE id = ? AND ${LIVE_PARENT}`\n        ).get(id) as Record<string, unknown> | undefined\n\n        if (!row) return null\n        const meta = rowToMeta(row)\n        const body = ContentRepository.getBody(meta.contentId, db)\n        return { ...meta, content: body ?? '', sourceDraft: rowToSourceDraft(row) }\n    }\n\n    /** 获取下一个修稿序号 */\n    static getNextIndex(baseDraftId: number): number {\n        const db = getProjectDb()\n        if (!db) return 1\n\n        const row = db.prepare(`\n      SELECT MAX(revision_index) as maxIdx FROM revisions WHERE base_draft_id = ?\n    `).get(baseDraftId) as { maxIdx: number | null }\n\n        return (row.maxIdx ?? 0) + 1\n    }\n\n    /**\n     * 将人工确认的合并正文、草稿状态和修订关系作为一个 SQLite 提交写入。\n     * revisionId 同时是天然的幂等身份：已完成的同一合并只返回读回结果，\n     * 不会再次覆盖之后产生的正文。\n     */\n    static mergeIntoDraft(request: MergeRevisionRequest, db = getProjectDb()): MergeRevisionReceipt {\n        if (!db) throw new Error('PROJECT_NOT_OPEN')\n\n        return db.transaction((): MergeRevisionReceipt => {\n            const target = db.prepare(`\n              SELECT drafts.chapter_number, drafts.version, drafts.status,\n                     drafts.word_count, drafts.content_id, contents.body\n              FROM drafts\n              JOIN contents ON contents.id = drafts.content_id\n              WHERE drafts.id = ?\n            `).get(request.targetDraftId) as {\n                status: string\n                chapter_number: number\n                version: number\n                word_count: number\n                content_id: number\n                body: string\n            } | undefined\n            if (!target) throw new Error('DRAFT_NOT_FOUND')\n\n            const revision = db.prepare(`\n              SELECT base_draft_id, status, merged_to_draft_id,\n                     source_draft_chapter_number, source_draft_version,\n                     source_draft_status, source_content\n              FROM revisions WHERE id = ?\n            `).get(request.revisionId) as {\n                base_draft_id: number\n                status: string\n                merged_to_draft_id: number | null\n                source_draft_chapter_number: number | null\n                source_draft_version: number | null\n                source_draft_status: string | null\n                source_content: string | null\n            } | undefined\n            if (!revision) throw new Error('REVISION_NOT_FOUND')\n            if (revision.base_draft_id !== request.targetDraftId) {\n                throw new Error('REVISION_TARGET_MISMATCH')\n            }\n\n            if (revision.status === 'merged') {\n                if (\n                    revision.merged_to_draft_id !== request.targetDraftId\n                    || target.body !== request.mergedContent\n                    || target.status !== 'revised'\n                    || target.word_count !== request.wordCount\n                ) {\n                    throw new Error('REVISION_ALREADY_MERGED')\n                }\n                let reviewCycle: MergeRevisionReceipt['reviewCycle']\n                if (hasReviewCycleSchema(db)) {\n                    const committed = ReviewCycleRepository.commitMergedRevision({\n                        revisionId: request.revisionId,\n                        mergedHash: contentHash(request.mergedContent),\n                    }, db)\n                    if (committed.bound && committed.cycleId) {\n                        const plan = ReviewCycleRepository.planRecheck(committed.cycleId, db)\n                        reviewCycle = { cycleId: committed.cycleId, mergedHash: contentHash(request.mergedContent),\n                            disposition: plan.disposition }\n                    }\n                }\n                return {\n                    revisionId: request.revisionId,\n                    targetDraftId: request.targetDraftId,\n                    status: 'revised',\n                    wordCount: request.wordCount,\n                    idempotent: true,\n                    chapterNumber: target.chapter_number,\n                    version: target.version,\n                    ...(reviewCycle ? { reviewCycle } : {}),\n                }\n            }\n            if (revision.status !== 'pending') {\n                throw new Error('REVISION_NOT_PENDING')\n            }\n            if (!['draft', 'revised', 'reviewed'].includes(target.status)) {\n                throw new Error('REVISION_TARGET_NOT_EDITABLE')\n            }\n            if (target.body !== request.expectedDraftContent) {\n                throw new Error('REVISION_TARGET_CHANGED')\n            }\n            if (\n                revision.source_draft_chapter_number === null\n                || revision.source_draft_version === null\n                || revision.source_draft_status === null\n                || revision.source_content === null\n            ) {\n                throw new Error('REVISION_SOURCE_MISSING')\n            }\n            if (\n                target.chapter_number !== revision.source_draft_chapter_number\n                || target.version !== revision.source_draft_version\n                || target.status !== revision.source_draft_status\n                || target.body !== revision.source_content\n            ) {\n                throw new Error('REVISION_SOURCE_MISMATCH')\n            }\n            db.prepare('UPDATE contents SET body = ? WHERE id = ?')\n                .run(request.mergedContent, target.content_id)\n            const draftUpdate = db.prepare(`\n              UPDATE drafts_all\n              SET status = 'revised', word_count = ?, updated_at = datetime('now')\n              WHERE id = ? AND status IN ('draft', 'revised', 'reviewed')\n            `).run(request.wordCount, request.targetDraftId)\n            if (draftUpdate.changes !== 1) {\n                throw new Error('REVISION_TARGET_CHANGED')\n            }\n            const revisionUpdate = db.prepare(`\n              UPDATE revisions\n              SET status = 'merged', merged_to_draft_id = ?, updated_at = datetime('now')\n              WHERE id = ? AND base_draft_id = ? AND status = 'pending'\n            `).run(request.targetDraftId, request.revisionId, request.targetDraftId)\n            if (revisionUpdate.changes !== 1) {\n                throw new Error('REVISION_NOT_PENDING')\n            }\n            let reviewCycle: MergeRevisionReceipt['reviewCycle']\n            if (hasReviewCycleSchema(db)) {\n                const committed = ReviewCycleRepository.commitMergedRevision({\n                    revisionId: request.revisionId,\n                    mergedHash: contentHash(request.mergedContent),\n                }, db)\n                if (committed.bound && committed.cycleId) {\n                    const plan = ReviewCycleRepository.planRecheck(committed.cycleId, db)\n                    reviewCycle = { cycleId: committed.cycleId, mergedHash: contentHash(request.mergedContent),\n                        disposition: plan.disposition }\n                }\n            }\n\n            return {\n                revisionId: request.revisionId,\n                targetDraftId: request.targetDraftId,\n                status: 'revised',\n                wordCount: request.wordCount,\n                idempotent: false,\n                chapterNumber: target.chapter_number,\n                version: target.version,\n                ...(reviewCycle ? { reviewCycle } : {}),\n            }\n        })()\n    }\n\n    /** 标记为已合并（仅 pending → merged） */\n    static markMerged(id: number, mergedToDraftId: number, db = getProjectDb()): void {\n        if (!db) throw new Error('PROJECT_NOT_OPEN')\n\n        db.transaction(() => {\n            if (hasReviewCycleSchema(db) && db.prepare('SELECT 1 FROM review_cycles WHERE revision_id=?').get(id)) {\n                throw new Error('REVISION_MERGE_REQUIRED')\n            }\n            const result = db.prepare(`\n      UPDATE revisions\n      SET status = 'merged', merged_to_draft_id = ?, updated_at = datetime('now')\n      WHERE id = ? AND status = 'pending' AND ${LIVE_PARENT}\n    `).run(mergedToDraftId, id)\n\n            if (result.changes === 0) {\n                throw new Error('REVISION_NOT_PENDING')\n            }\n        })()\n    }\n\n    /** 标记为已弃用（仅 pending → discarded） */\n    static markDiscarded(id: number, db = getProjectDb()): void {\n        if (!db) throw new Error('PROJECT_NOT_OPEN')\n\n        db.transaction(() => {\n            const result = db.prepare(`\n      UPDATE revisions SET status = 'discarded', updated_at = datetime('now')\n      WHERE id = ? AND status = 'pending' AND ${LIVE_PARENT}\n    `).run(id)\n\n            if (result.changes === 0) {\n                throw new Error('REVISION_NOT_PENDING')\n            }\n            if (hasReviewCycleSchema(db)) {\n                ReviewCycleRepository.reconcileDiscardedRevisions([id], db)\n            }\n        })()\n    }\n}\n"
    },
    {
      "path": "electron/services/finalization-service.ts",
      "content": "import { createHash, randomUUID } from 'node:crypto'\n\nimport {\n  FinalizationRepository,\n  type FinalizationRecord,\n  type PublicationStatus,\n} from '../repositories/finalization-repository'\nimport { ChapterDeletionRepository } from '../repositories/chapter-deletion-repository'\nimport { getCurrentProjectPath } from '../database'\nimport { assertRequiredExpectedProjectPath } from '../utils/project-context'\nimport {\n  manuscriptPublisher,\n  resolveManuscriptTarget,\n  type PublishManuscriptInput,\n} from './manuscript-publisher'\nimport { PortableRuntimeFreezeError, readPortableRuntimeFreeze } from './portable-runtime-freeze'\n\nexport interface FinalizationRequest {\n  /** 已由 ProjectAccess 验证并 canonicalize 的项目根目录。 */\n  projectRoot: string\n  draftId: number\n  chapterNumber: number\n  chapterTitle: string\n  content: string\n  contentRevision: number\n}\n\nexport interface FinalizationRetryRequest {\n  /** 已由 ProjectAccess 验证并 canonicalize 的项目根目录。 */\n  projectRoot: string\n  finalizationId: string\n}\n\nexport interface FinalizationResult {\n  success: boolean\n  /** false 代表数据库事务从未提交；true 则数据库定稿事实已存在。 */\n  committed: boolean\n  finalizationId?: string\n  contentHash?: string\n  contentRevision?: number\n  draftId?: number\n  publicationStatus?: PublicationStatus\n  error?: string\n}\n\nexport interface FinalizationPublisher {\n  publish(input: PublishManuscriptInput): Promise<void>\n}\n\nexport interface FinalizationServiceOptions {\n  createFinalizationId?: () => string\n  publisher?: FinalizationPublisher\n}\n\nfunction toResult(record: FinalizationRecord, success: boolean, error?: string): FinalizationResult {\n  return {\n    success,\n    committed: true,\n    finalizationId: record.finalizationId,\n    contentHash: record.contentHash,\n    contentRevision: record.contentRevision,\n    draftId: record.draftId,\n    publicationStatus: record.publicationStatus,\n    ...(error ? { error } : {}),\n  }\n}\n\nfunction snapshotHash(content: string): string {\n  return createHash('sha256').update(content, 'utf8').digest('hex')\n}\n\nfunction hasSameFrozenRequest(\n  record: FinalizationRecord,\n  request: FinalizationRequest,\n  contentHash: string,\n): boolean {\n  return record.draftId === request.draftId\n    && record.chapterNumber === request.chapterNumber\n    && record.chapterTitle === request.chapterTitle\n    && record.contentRevision === request.contentRevision\n    && record.contentHash === contentHash\n    && record.contentSnapshot === request.content\n}\n\nfunction snapshotIntegrityError(record: FinalizationRecord): string | null {\n  return snapshotHash(record.contentSnapshot) === record.contentHash\n    ? null\n    : 'FINALIZATION_SNAPSHOT_HASH_MISMATCH'\n}\n\n/**\n * 主进程定稿应用服务：SQLite transaction 是事实源，实体稿仅为可恢复投影。\n * retry 只接收 finalizationId，正文、标题和目标文件名都只从已提交 outbox 读取。\n */\nexport class FinalizationService {\n  private readonly createFinalizationId: () => string\n  private readonly publisher: FinalizationPublisher\n\n  constructor(options: FinalizationServiceOptions = {}) {\n    this.createFinalizationId = options.createFinalizationId ?? randomUUID\n    this.publisher = options.publisher ?? manuscriptPublisher\n  }\n\n  async finalize(request: FinalizationRequest): Promise<FinalizationResult> {\n    const finalizationId = this.createFinalizationId()\n    const contentHash = snapshotHash(request.content)\n    let record: FinalizationRecord\n    try {\n      const existing = FinalizationRepository.getByDraftId(request.draftId)\n      if (existing) {\n        if (!hasSameFrozenRequest(existing, request, contentHash)) {\n          return {\n            success: false,\n            committed: false,\n            error: 'FINALIZATION_COMMIT_CONFLICT',\n          }\n        }\n        // 上次响应可能在客户端收到前丢失。复用既有 finalizationId 与目标文件名，\n        // 而不是因新的 UUID 或文件碰撞创建第二次提交。\n        return this.publishCommitted(request.projectRoot, existing)\n      }\n      const target = resolveManuscriptTarget({\n        projectRoot: request.projectRoot,\n        chapterNumber: request.chapterNumber,\n        chapterTitle: request.chapterTitle,\n        finalizationId,\n        // 删除清理还没记完的文件名不能用：续跑那次清理会把新发布的这份删掉。\n        reserved: ChapterDeletionRepository.reservedManuscriptTargets(),\n      })\n      record = FinalizationRepository.commit({\n        finalizationId,\n        draftId: request.draftId,\n        chapterNumber: request.chapterNumber,\n        chapterTitle: request.chapterTitle,\n        content: request.content,\n        contentHash,\n        contentRevision: request.contentRevision,\n        targetFileName: target.fileName,\n      })\n    } catch (error) {\n      return {\n        success: false,\n        committed: false,\n        finalizationId,\n        contentHash,\n        contentRevision: request.contentRevision,\n        draftId: request.draftId,\n        error: String(error),\n      }\n    }\n    return this.publishCommitted(request.projectRoot, record)\n  }\n\n  async retry(request: FinalizationRetryRequest): Promise<FinalizationResult> {\n    let record: FinalizationRecord | null\n    try {\n      record = FinalizationRepository.get(request.finalizationId)\n    } catch (error) {\n      return { success: false, committed: false, error: String(error) }\n    }\n    if (!record) {\n      return {\n        success: false,\n        committed: false,\n        finalizationId: request.finalizationId,\n        error: 'FINALIZATION_COMMIT_NOT_FOUND',\n      }\n    }\n    const integrityError = snapshotIntegrityError(record)\n    if (integrityError) {\n      return toResult(record, false, integrityError)\n    }\n    if (record.publicationStatus === 'published') {\n      return toResult(record, true)\n    }\n    return this.publishCommitted(request.projectRoot, record)\n  }\n\n  private async publishCommitted(projectRoot: string, record: FinalizationRecord): Promise<FinalizationResult> {\n    try {\n      readPortableRuntimeFreeze(projectRoot).assertMutable('finalization_outbox', record.finalizationId)\n    } catch (error) {\n      const message = error instanceof PortableRuntimeFreezeError ? error.code : String(error)\n      return toResult(record, false, message)\n    }\n    try {\n      const integrityError = snapshotIntegrityError(record)\n      if (integrityError) throw new Error(integrityError)\n      if (record.publicationStatus === 'published') {\n        return toResult(record, true)\n      }\n      if (!FinalizationRepository.isAuthoritative(record.draftId)) {\n        return toResult(record, false, 'FINALIZATION_SUPERSEDED')\n      }\n      await this.publisher.publish({\n        projectRoot,\n        targetFileName: record.targetFileName,\n        chapterNumber: record.chapterNumber,\n        chapterTitle: record.chapterTitle,\n        content: record.contentSnapshot,\n      })\n      // 写实体稿期间换了作品：发布结果不记进另一部作品的库；原作品的 outbox 仍是待发布，重新打开后重试即可（同内容幂等）。\n      assertRequiredExpectedProjectPath(getCurrentProjectPath(), projectRoot)\n      return toResult(FinalizationRepository.markPublished(record.finalizationId), true)\n    } catch (error) {\n      // committed: true 已表明定稿已提交、实体稿待发布，各显示处自己写这句；error 只带原因（错误码或系统报错）。\n      const message = String(error)\n      try {\n        assertRequiredExpectedProjectPath(getCurrentProjectPath(), projectRoot)\n      } catch {\n        return toResult(record, false, message)\n      }\n      try {\n        const pending = FinalizationRepository.markPublicationPending(record.finalizationId, message)\n        return toResult(pending, false, message)\n      } catch (markError) {\n        // outbox 在事务内已经以 pending 创建；即使补记错误失败，也不能把已提交事实伪装为回滚。\n        console.error('[finalization] 实体稿待发布状态记录失败:', markError)\n        return toResult(record, false, message)\n      }\n    }\n  }\n}\n"
    },
    {
      "path": "electron/services/generation-draft-effects.ts",
      "content": "import type Database from 'better-sqlite3'\nimport { isDeepStrictEqual } from 'node:util'\nimport type { MainGenerationRunHandle } from '../../src/services/generation/generation-runtime'\nimport { MAX_BATCH_CHAPTERS, type GenerationBatchIntent, type GenerationBatchProgress, type GenerationBatchHistory, type GenerationDraftCommitReceipt, type GenerationDraftCommitRequest, type GenerationDraftSaveState } from '../../src/shared/generation-owner-contract'\nimport type { DraftSourceDependency } from '../../src/shared/draft-source-dependency'\nimport { countDraftUnits, draftTargetUnitRange } from '../../src/shared/draft-units'\nimport { isDraftVisibleTextVersion } from '../../src/shared/draft-visible-text'\nimport { isReceiptedDraftStatus } from '../../src/shared/draft-status'\nimport { GenerationRunRepository, textHash, type DurableGenerationRun } from '../repositories/generation-run-repository'\nimport { DraftRepository } from '../repositories/draft-repository'\n\ninterface StoredDraftCommit extends GenerationDraftCommitReceipt {\n  chapterNumber: number\n  handle: MainGenerationRunHandle\n  batchId?: string\n}\ninterface AttemptRow { attempt_id: string; run_id: string; usage_receipt_json: string }\ntype BatchSourceConflict = 'GENERATION_DRAFT_RECEIPT_INVALID' | 'GENERATION_BATCH_DRAFT_REPLACED' | 'GENERATION_BATCH_FINALIZATION_CONFLICT'\ntype VerifiedBatchSnapshot = { progress: GenerationBatchProgress; sourceConflict: BatchSourceConflict | null }\nconst handleOf = (run: DurableGenerationRun): MainGenerationRunHandle => ({ projectId: run.binding.projectId,\n  epoch: run.binding.epoch, rootActionId: run.rootActionId, runId: run.runId })\nexport function assertGenerationBatchIntent(intent: GenerationBatchIntent): void {\n  if (!intent || !['draft_review', 'auto_finalize'].includes(intent.mode) || !intent.range\n    || !Number.isSafeInteger(intent.range.startChapter) || !Number.isSafeInteger(intent.range.endChapter)\n    || intent.range.startChapter < 1 || intent.range.endChapter < intent.range.startChapter\n    || intent.range.endChapter - intent.range.startChapter >= MAX_BATCH_CHAPTERS\n    || !Number.isSafeInteger(intent.targetUnits) || intent.targetUnits < 1 || intent.targetUnits > 1_000_000)\n    throw new Error('GENERATION_BATCH_INTENT_INVALID')\n}\n\nfunction groupByBatch(rows: (AttemptRow & { batch_id: string })[]): ReadonlyMap<string, AttemptRow[]> {\n  const groups = new Map<string, AttemptRow[]>()\n  for (const { batch_id: id, ...row } of rows) {\n    const group = groups.get(id)\n    if (group) group.push(row)\n    else groups.set(id, [row])\n  }\n  return groups\n}\n/** Existing generation attempt receipts are the only draft/batch ledger. */\nexport class GenerationDraftEffects {\n  constructor(private readonly db: Database.Database, private readonly runs: GenerationRunRepository) {}\n  private attempts(runId: string): AttemptRow[] {\n    return this.db.prepare('SELECT attempt_id,run_id,usage_receipt_json FROM generation_attempts WHERE run_id=? ORDER BY rowid').all(runId) as AttemptRow[]\n  }\n  /** 按批次号分组的草稿提交收据，按提交顺序；只取这一批时传 batchId。批次号由库里的 JSON 取出，不在这里逐行解析整份收据。 */\n  batchCommits(batchId?: string): ReadonlyMap<string, AttemptRow[]> {\n    const batchOf = \"json_extract(usage_receipt_json,'$.draftCommit.batchId')\"\n    const rows = this.db.prepare(`SELECT attempt_id,run_id,usage_receipt_json,${batchOf} AS batch_id\n      FROM generation_attempts WHERE ${batchOf} ${batchId === undefined ? 'IS NOT NULL' : '= ?'} ORDER BY rowid`)\n      .all(...(batchId === undefined ? [] : [batchId])) as (AttemptRow & { batch_id: string })[]\n    return groupByBatch(rows)\n  }\n  /**\n   * 列表用的分组：收据不是合法 JSON 的行读不出批次号，跳过并计数，其余批次照常分组。\n   * 只用于显示；续跑与提交走 readBatch 的严格查询，遇到坏行仍会报错。\n   */\n  listedBatchCommits(): { commits: ReadonlyMap<string, AttemptRow[]>; unreadable: number } {\n    const unreadable = this.db.prepare('SELECT COUNT(*) FROM generation_attempts WHERE NOT json_valid(usage_receipt_json)').pluck().get() as number\n    const batchOf = \"CASE WHEN json_valid(usage_receipt_json) THEN json_extract(usage_receipt_json,'$.draftCommit.batchId') END\"\n    const rows = this.db.prepare(`SELECT attempt_id,run_id,usage_receipt_json,${batchOf} AS batch_id\n      FROM generation_attempts WHERE ${batchOf} IS NOT NULL ORDER BY rowid`).all() as (AttemptRow & { batch_id: string })[]\n    return { commits: groupByBatch(rows), unreadable }\n  }\n  /** settledChapter 这一章按已确认完（已发布、后处理关键步骤都完成）算进度，用于放回删除前已确认完的章：放回会把它重置为待发布、待重导。 */\n  unfinishedBatchChapters(projectId: string, settledChapter?: number): ReadonlySet<number> {\n    const { commits } = this.listedBatchCommits()\n    // 已取消、已封存或被阻断的批次再也续不上（续写只接受 active、paused 且未阻断的根），它写过的章不必为续写锁住。\n    const roots = this.db.prepare(`SELECT r.run_id FROM generation_runs r JOIN generation_roots g ON g.root_action_id=r.root_action_id\n      WHERE json_valid(r.binding_json) AND json_extract(r.binding_json,'$.sourceManifest.batchIntent') IS NOT NULL\n      AND COALESCE(CASE WHEN json_valid(g.action_json) THEN json_extract(g.action_json,'$.status') END,'') NOT IN ('cancelled','sealed')\n      AND g.blocked_code IS NULL`)\n      .pluck().all() as string[]\n    const chapters = new Set<number>()\n    for (const batchId of roots) {\n      try {\n        const history = this.readBatchHistory(batchId, projectId, commits, settledChapter)\n        if (history.sourceCurrent && history.nextChapterNumber !== null) for (const chapter of history.completedChapters) chapters.add(chapter.chapterNumber)\n      } catch (error) {\n        if (!(error instanceof Error && error.message.startsWith('GENERATION_'))) throw error\n      }\n    }\n    return chapters\n  }\n  /** 这份定稿已发布、后处理关键步骤都完成。读 _all 表，回收站里的定稿也能查：删除不动 outbox 与后处理，它们仍是删除前的状态。 */\n  finalizationSettled(finalizationId: string): boolean {\n    return this.db.prepare(\"SELECT 1 FROM finalization_outbox_all WHERE finalization_id=? AND publication_status='published'\").get(finalizationId) !== undefined\n      && this.postProcessComplete(finalizationId)\n  }\n  private postProcessComplete(finalizationId: string): boolean {\n    const postProcess = this.db.prepare(\"SELECT id,all_critical_passed FROM post_process_runs WHERE trigger_source_type='chapter_finalize' AND trigger_source_id=? ORDER BY created_at DESC,rowid DESC LIMIT 1\").get(`finalization:${finalizationId}`) as { id: string; all_critical_passed: number } | undefined\n    const steps = postProcess ? this.db.prepare('SELECT step_key,critical,ok FROM post_process_steps WHERE run_id=?').all(postProcess.id) as { step_key: string; critical: number; ok: number }[] : []\n    return postProcess?.all_critical_passed === 1 && ['kb_import', 'chapter_notes'].every(key => steps.some(step => step.step_key === key && step.critical === 1 && step.ok === 1))\n      && steps.filter(step => step.critical === 1).every(step => step.ok === 1)\n  }\n  private verifiedCommit(row: AttemptRow) {\n    const usage = JSON.parse(row.usage_receipt_json), stored = usage.draftCommit as StoredDraftCommit | undefined\n    if (!stored) return null\n    const run = this.runs.get(row.run_id), composition = this.runs.readVisibleComposition(run.runId)\n    const draft = this.db.prepare('SELECT d.id,d.version,d.chapter_number,d.status,c.body FROM drafts d JOIN contents c ON c.id=d.content_id WHERE d.id=?').get(stored.id) as { id: number; version: number; chapter_number: number; status: string; body: string } | undefined\n    if (!composition || !isDraftVisibleTextVersion(composition.algorithm) || stored.success !== true\n      || stored.chapterNumber !== run.binding.sourceManifest.chapterNumber\n      || draft && (stored.chapterNumber !== draft.chapter_number || stored.version !== draft.version) || stored.contentHash !== textHash(stored.content) || stored.contentHash !== composition.textHash\n      || stored.content !== composition.text || stored.batchId !== run.binding.sourceManifest.batchId\n      || !isDeepStrictEqual(stored.handle, { ...handleOf(run), epoch: usage.artifactIdentity?.epoch }))\n      throw new Error('GENERATION_DRAFT_RECEIPT_INVALID')\n    return { receipt: stored, matchesBody: !!draft && stored.content === draft.body, draft }\n  }\n  private readSaveState(runId: string) {\n    const commits = this.attempts(runId).map(row => this.verifiedCommit(row)).filter(item => item !== null)\n    if (commits.length > 1) throw new Error('GENERATION_DRAFT_RECEIPT_INVALID')\n    return commits[0] ?? null\n  }\n  readCommit(runId: string): StoredDraftCommit | null {\n    const saved = this.readSaveState(runId)\n    if (saved && !saved.matchesBody) throw new Error('GENERATION_DRAFT_RECEIPT_INVALID')\n    return saved?.receipt ?? null\n  }\n  readRecovery(runId: string): GenerationDraftSaveState {\n    const saved = this.readSaveState(runId)\n    if (!saved) return { kind: 'absent' }\n    if (!saved.matchesBody) return { kind: 'changed' }\n    const { id, version, content, contentHash } = saved.receipt\n    return { kind: 'current', receipt: { success: true, id, version, content, contentHash } }\n  }\n  readBatch(batchId: string, projectId: string): GenerationBatchProgress {\n    const snapshot = this.readBatchSnapshot(batchId, projectId)\n    if (snapshot.sourceConflict) throw new Error(snapshot.sourceConflict)\n    return snapshot.progress\n  }\n  readBatchHistory(batchId: string, projectId: string, commits = this.batchCommits(batchId), settledChapter?: number): GenerationBatchHistory {\n    const snapshot = this.readBatchSnapshot(batchId, projectId, commits, settledChapter)\n    return { ...snapshot.progress, sourceCurrent: snapshot.sourceConflict === null }\n  }\n  private readBatchSnapshot(batchId: string, projectId: string, commits = this.batchCommits(batchId), settledChapter?: number): VerifiedBatchSnapshot {\n    const root = this.runs.get(batchId), intent = root.binding.sourceManifest.batchIntent as GenerationBatchIntent\n    assertGenerationBatchIntent(intent)\n    if (root.binding.projectId !== projectId || root.binding.sourceManifest.operation !== 'batch-chapters') throw new Error('GENERATION_BATCH_IDENTITY_INVALID')\n    const completedChapters: GenerationBatchProgress['completedChapters'] = []\n    let sourceConflict: BatchSourceConflict | null = null\n    for (const row of commits.get(batchId) ?? []) {\n      const saved = this.verifiedCommit(row)!\n      if (!saved.matchesBody) sourceConflict ??= 'GENERATION_DRAFT_RECEIPT_INVALID'\n      const committed = saved.receipt\n      if (committed.handle.rootActionId !== root.rootActionId) throw new Error('GENERATION_BATCH_LINEAGE_INVALID')\n      const latest = this.db.prepare('SELECT id FROM drafts WHERE chapter_number=? ORDER BY version DESC,id DESC LIMIT 1').pluck().get(committed.chapterNumber)\n      if (latest !== committed.id || saved.draft?.status === 'superseded') sourceConflict ??= 'GENERATION_BATCH_DRAFT_REPLACED'\n      let outbox = this.db.prepare('SELECT finalization_id,content_hash,content_snapshot,chapter_number,publication_status FROM finalization_outbox WHERE draft_id=?').get(committed.id) as {\n        finalization_id: string; content_hash: string; content_snapshot: string; chapter_number: number; publication_status: string\n      } | undefined\n      if (outbox && (outbox.content_hash !== textHash(outbox.content_snapshot) || outbox.chapter_number !== committed.chapterNumber))\n        throw new Error('GENERATION_BATCH_FINALIZATION_CONFLICT')\n      if (outbox && outbox.content_snapshot !== committed.content) {\n        if (!isReceiptedDraftStatus(saved.draft?.status ?? '') || saved.draft?.body !== outbox.content_snapshot)\n          throw new Error('GENERATION_BATCH_FINALIZATION_CONFLICT')\n        sourceConflict ??= 'GENERATION_BATCH_FINALIZATION_CONFLICT'\n        outbox = undefined\n      }\n      const postProcessComplete = outbox ? this.postProcessComplete(outbox.finalization_id) : false\n      completedChapters.push({ chapterNumber: committed.chapterNumber, draftId: committed.id, version: committed.version,\n        contentHash: committed.contentHash, sourceRunHandle: handleOf(this.runs.get(row.run_id)), postProcessComplete,\n        ...(outbox?.publication_status === 'published' ? { finalizationId: outbox.finalization_id } : outbox ? { pendingFinalizationId: outbox.finalization_id } : {}) })\n    }\n    completedChapters.sort((a, b) => a.chapterNumber - b.chapterNumber)\n    let nextChapterNumber: number | null = intent.range.startChapter\n    for (const [index, chapter] of completedChapters.entries()) {\n      if (chapter.chapterNumber !== intent.range.startChapter + index || chapter.chapterNumber > intent.range.endChapter\n        || nextChapterNumber !== chapter.chapterNumber) throw new Error('GENERATION_BATCH_PROGRESS_INVALID')\n      if (intent.mode === 'auto_finalize' && chapter.chapterNumber !== settledChapter && (!chapter.finalizationId || !chapter.postProcessComplete)) break\n      nextChapterNumber = chapter.chapterNumber === intent.range.endChapter ? null : chapter.chapterNumber + 1\n    }\n    // 审稿批次不替作者定稿；作者开始定稿其中一章即结束这一批，剩下的章另起一批（#568）。\n    // 按章查：作者定稿的可能是该章更旧的草稿。批次只能写还没定稿的章，所以这里查到的定稿都在批次之后。\n    const chapterFinalized = this.db.prepare('SELECT 1 FROM finalization_outbox WHERE chapter_number=? LIMIT 1').pluck()\n    if (intent.mode === 'draft_review' && nextChapterNumber !== null\n      && completedChapters.some(chapter => chapterFinalized.get(chapter.chapterNumber))) sourceConflict ??= 'GENERATION_BATCH_FINALIZATION_CONFLICT'\n    const pending = (this.db.prepare('SELECT run_id FROM generation_runs WHERE root_action_id=?').all(root.rootActionId) as { run_id: string }[])\n      .map(row => this.runs.get(row.run_id)).filter(run => run.binding.sourceManifest.batchId === batchId\n        && run.binding.sourceManifest.chapterNumber === nextChapterNumber && !this.readSaveState(run.runId))\n    if (pending.length > 1) throw new Error('GENERATION_BATCH_PROGRESS_INVALID')\n    return { sourceConflict, progress: { ...structuredClone(intent), modelId: (root.binding.sourceManifest.modelReceipt as { modelId: string }).modelId, batchId, rootHandle: handleOf(root), completedChapters, nextChapterNumber,\n      ...(pending[0] ? { currentChapterRunHandle: handleOf(pending[0]) } : {}),\n      authorInputs: structuredClone(root.binding.sourceManifest.authorInputs as GenerationBatchProgress['authorInputs'] ?? []) } }\n  }\n  commit(request: GenerationDraftCommitRequest, assertSources: () => void): GenerationDraftCommitReceipt {\n    return this.db.transaction(() => {\n      const run = this.runs.get(request.handle.runId), previous = this.readCommit(run.runId)\n      if (request.source !== 'write' || request.chapterNumber !== run.binding.sourceManifest.chapterNumber\n        || run.binding.sourceManifest.operation !== 'chapter-draft' || request.batchId !== run.binding.sourceManifest.batchId)\n        throw new Error('GENERATION_DRAFT_TARGET_INVALID')\n      if (previous) {\n        if (previous.contentHash !== request.expectedCompositionHash) throw new Error('GENERATION_DRAFT_COMMIT_CONFLICT')\n        return { success: true as const, id: previous.id, version: previous.version, content: previous.content, contentHash: previous.contentHash }\n      }\n      assertSources()\n      const composition = this.runs.readVisibleComposition(run.runId)\n      if (!composition || !isDraftVisibleTextVersion(composition.algorithm) || composition.textHash !== request.expectedCompositionHash)\n        throw new Error('GENERATION_DRAFT_COMPOSITION_REQUIRED')\n      const artifact = this.db.prepare('SELECT attempt_id FROM generation_artifacts WHERE artifact_id=?').pluck().get(composition.artifactIds.at(-1)) as string\n      if (this.runs.receipt(artifact).result?.finishReason !== 'stop') throw new Error('GENERATION_DRAFT_INCOMPLETE')\n      const target = Number((run.binding.sourceManifest.authorInputs as { id: string; text: string }[] | undefined)?.find(item => item.id === 'draft:target-units')?.text)\n      if (!Number.isSafeInteger(target) || target < 1) throw new Error('GENERATION_DRAFT_INCOMPLETE')\n      const units = countDraftUnits(composition.text), range = draftTargetUnitRange(target)\n      if (units < range.minimum) throw new Error('GENERATION_DRAFT_INCOMPLETE')\n      if (request.batchId) {\n        const progress = this.readBatch(request.batchId, request.handle.projectId)\n        if (progress.rootHandle.rootActionId !== run.rootActionId || progress.nextChapterNumber !== request.chapterNumber\n          || progress.targetUnits !== target\n          || progress.completedChapters.some(item => item.chapterNumber === request.chapterNumber)) throw new Error('GENERATION_BATCH_PROGRESS_CONFLICT')\n      }\n      const dependencies: DraftSourceDependency[] = run.binding.sourceRefs.flatMap(ref => {\n        const candidate = /^draft:(\\d+)$/.exec(ref.sourceId)\n        if (candidate) return [{ kind: 'candidate' as const, draftId: Number(candidate[1]), contentHash: ref.contentHash }]\n        return []\n      })\n      for (const ref of run.binding.sourceRefs) {\n        const finalized = /^finalized:(\\d+):(.+)$/.exec(ref.sourceId)\n        if (!finalized) continue\n        const chapterNumber = this.db.prepare('SELECT chapter_number FROM drafts WHERE id=?').pluck().get(Number(finalized[1])) as number\n        dependencies.push({ kind: 'finalized', draftId: Number(finalized[1]), finalizationId: finalized[2]!, chapterNumber, contentHash: ref.contentHash })\n      }\n      const id = DraftRepository.create({ chapterNumber: request.chapterNumber, source: 'write', content: composition.text,\n        wordCount: units, sourceDependencies: dependencies }, this.db)\n      const version = this.db.prepare('SELECT version FROM drafts WHERE id=?').pluck().get(id) as number\n      const receipt: GenerationDraftCommitReceipt = { success: true, id, version, contentHash: composition.textHash, content: composition.text }\n      const row = this.attempts(run.runId).find(item => item.attempt_id === artifact)!\n      const usage = JSON.parse(row.usage_receipt_json)\n      const stored: StoredDraftCommit = { ...receipt, chapterNumber: request.chapterNumber,\n        handle: { ...request.handle, epoch: usage.artifactIdentity.epoch }, ...(request.batchId ? { batchId: request.batchId } : {}) }\n      this.db.prepare('UPDATE generation_attempts SET usage_receipt_json=? WHERE attempt_id=?').run(JSON.stringify({ ...usage, draftCommit: stored }), artifact)\n      if (request.batchId) this.readBatch(request.batchId, request.handle.projectId)\n      return receipt\n    }).immediate()\n  }\n}\n"
    },
    {
      "path": "electron/services/generation-run-service.ts",
      "content": "import { isDeepStrictEqual } from 'node:util';\nimport { isTerminalProviderFailure, safeTransportError, type GenerationTransportDiagnostics } from '../../src/shared/generation-contract';\nimport { GenerationRunRepository, type OpenGenerationRunRequest, type RunBinding, type GenerationExecutionReceipt, type GenerationUsageReceipt } from '../repositories/generation-run-repository';\nimport type { ProviderUsagePolicy } from '../../src/shared/generation-contract';\nimport { parseAgentResponseProtocol, projectInterruptedAgentVisibleText } from '../../src/shared/agent-response-protocol';\nexport type { OpenGenerationRunRequest, RunBinding, DurableGenerationRun, GenerationExecutionReceipt, GenerationBudgetReceipt } from '../repositories/generation-run-repository';\nexport interface VisibleGenerationEvent {\n    kind: 'delta' | 'cumulative';\n    text: string;\n    eventId?: string;\n}\nexport interface GenerationProviderUsage {\n    promptTokens: number | null;\n    completionTokens: number | null;\n    totalTokens: number | null;\n    reasoningTokens: number | null;\n    accounting: 'included-in-completion' | 'separately-billed' | 'unknown';\n    totalIncludesReasoning: boolean;\n    /** Set only by the trusted provider adapter for a known protocol. */\n    trusted: boolean;\n}\nexport interface GenerationDispatchResult {\n    usage: GenerationProviderUsage | null;\n    finishReason: string | null;\n}\nexport interface GenerationUnsavedTail {\n    attemptId: string;\n    artifactId: string;\n    durableRevision: number;\n    text: string;\n    failureCode: 'GENERATION_STORAGE_FAILED';\n}\n/** Internal main-only request. The IPC controller supplies the frozen plan and lease, never renderer estimates. */\nexport interface ExecuteGenerationRequest {\n    runId: string;\n    invocationNonce: string;\n    requestHash: string;\n    providerRequest: unknown;\n    reservedTokens: number;\n    requestedOutputTokens: number;\n    inputUpperBoundTokens: number;\n    reasoningUpperBoundTokens: number;\n    usagePolicy: ProviderUsagePolicy;\n    purpose?: string;\n    budgetDecision?: import('../../src/services/generation/task-budget-planner').TaskBudgetDecision;\n    /** Main-only output projection selected from the frozen Agent tool manifest. */\n    agentToolNames?: readonly string[];\n    /** The original semantic task is committed with the reservation before dispatch. */\n    replayTask?: import('../../src/services/generation/generation-harness').GenerationTask;\n    /** 首稿提示经主进程复核确实带有生成前定稿对账注入块；恢复据此决定续写/压缩是否沿用对账结果。 */\n    reconciliationInjected?: boolean;\n}\n/** 作者暂停、取消、重开或本次运行总时长用尽时中止请求的原因；调用记录据此记为已取消，而不是服务商失败。存储失败、流不合规与关闭作品的中止不带它。 */\nexport const GENERATION_STOPPED = new DOMException('GENERATION_STOPPED', 'AbortError');\nexport interface GenerationRunServiceDependencies {\n    repository: GenerationRunRepository;\n    dispatch: (request: unknown, options: {\n        signal: AbortSignal;\n        onVisible: (event: VisibleGenerationEvent) => void;\n        onReasoning?: (text: string) => void;\n        onDiagnostics?: (diagnostics: GenerationTransportDiagnostics) => void;\n    }) => Promise<GenerationDispatchResult>;\n    /** Renderer-only projection. Reasoning never enters an artifact or receipt. */\n    onReasoning?: (event: { runId: string; rootActionId: string; attemptId: string; text: string }) => void;\n    onSnapshot?: (event: {\n        attemptId: string;\n        visibleText: string;\n        durableText: string;\n        durableRevision: number;\n        storageFailed: boolean;\n        diagnostics?: GenerationTransportDiagnostics;\n    }) => void;\n    validateRecovery?: (previous: RunBinding, next: RunBinding) => Promise<boolean>;\n}\nexport function settleProviderUsage(usage: GenerationProviderUsage | null, policy: ProviderUsagePolicy): GenerationUsageReceipt {\n    const conservative: GenerationUsageReceipt = { policy, trusted: false };\n    if (!usage?.trusted)\n        return conservative;\n    const { promptTokens: p, completionTokens: c, reasoningTokens: r, totalTokens: t } = usage;\n    if (p === null || c === null || !Number.isSafeInteger(p) || !Number.isSafeInteger(c) || p < 0 || c < 0\n        || r !== null && (!Number.isSafeInteger(r) || r < 0) || t !== null && (!Number.isSafeInteger(t) || t < 0))\n        return conservative;\n    if (policy.reasoning === 'unknown') {\n        // Trust only a reported, arithmetically consistent total. The adapter's\n        // protocol label cannot establish an unknown supplier's billing rules.\n        if (t === null || !Number.isSafeInteger(p + c)\n            || !(t === p + c && (r === null || r <= c) || r !== null && t === p + c + r)) return conservative;\n        return { policy, trusted: true, inputTokens: p, completionTokens: c,\n            ...(r !== null ? { reasoningTokens: r } : {}), actualTokens: t };\n    }\n    if (usage.accounting === 'unknown' || usage.accounting !== policy.reasoning)\n        return conservative;\n    if (usage.accounting === 'included-in-completion' && r !== null && r > c)\n        return conservative;\n    if (usage.accounting === 'separately-billed' && r === null)\n        return conservative;\n    const actual = p + c + (usage.accounting === 'separately-billed' ? r! : 0);\n    const expectedTotal = p + c + (usage.accounting === 'separately-billed' && usage.totalIncludesReasoning ? r! : 0);\n    if (t !== null && t !== expectedTotal || !Number.isSafeInteger(actual))\n        return conservative;\n    return { policy, trusted: true, inputTokens: p, completionTokens: c, ...(r !== null ? { reasoningTokens: r } : {}), actualTokens: actual };\n}\nexport function createGenerationRunService(deps: GenerationRunServiceDependencies) {\n    const controllers = new Map<string, {\n        controller: AbortController;\n        rootId: string;\n        flush: () => void;\n        suspend: () => void;\n    }>(), pending = new Map<string, Promise<GenerationExecutionReceipt>>();\n    const failedRoots = new Set<string>();\n    const unsavedTails = new Map<string, GenerationUnsavedTail>();\n    const execute = async (request: ExecuteGenerationRequest): Promise<GenerationExecutionReceipt> => {\n        const requestHash = request.requestHash;\n        if (!/^[a-f0-9]{64}$/u.test(requestHash))\n            throw new Error('GENERATION_REQUEST_HASH_INVALID');\n        const key = JSON.stringify([request.runId, request.invocationNonce]);\n        const existing = deps.repository.findInvocation(request.runId, request.invocationNonce, requestHash);\n        if (existing)\n            return pending.get(key) ?? existing;\n        if (pending.has(key))\n            return pending.get(key)!;\n        const operation = (async () => {\n            const run = deps.repository.get(request.runId);\n            if (failedRoots.has(run.rootActionId))\n                throw new Error('GENERATION_STORAGE_FAILED');\n            const { usagePolicy: policy } = request;\n            if (typeof policy.canBoundTotalLiability !== 'boolean' || !policy.estimatorVersion || !Number.isSafeInteger(policy.safetyMarginTokens) || policy.safetyMarginTokens < 0\n                || ![request.inputUpperBoundTokens, request.reasoningUpperBoundTokens].every(v => Number.isSafeInteger(v) && v >= 0)\n                || request.reservedTokens < request.inputUpperBoundTokens + request.requestedOutputTokens + request.reasoningUpperBoundTokens + policy.safetyMarginTokens)\n                throw new Error('GENERATION_RESERVATION_INVALID');\n            let receipt: GenerationExecutionReceipt;\n            try {\n                receipt = deps.repository.reserve(request.runId, request.invocationNonce, requestHash, request.reservedTokens, request.requestedOutputTokens, policy, request.purpose, request.replayTask, request.budgetDecision, request.reconciliationInjected);\n            }\n            catch (error) {\n                if (!/BUDGET|RESERVATION|EPOCH|DISPATCH|INVOCATION|CANCELLED/.test(error instanceof Error ? error.message : '')) {\n                    failedRoots.add(run.rootActionId);\n                    try {\n                        deps.repository.block(run.rootActionId, 'GENERATION_STORAGE_FAILED');\n                    }\n                    catch { /* The in-memory failure fence remains authoritative if storage is unavailable. */ }\n                }\n                throw error;\n            }\n            if (receipt.attempt.status !== 'reserved')\n                return receipt;\n            const attemptId = receipt.attempt.attemptId, controller = new AbortController();\n            let text = receipt.artifact!.text, durable = text, revision = receipt.artifact!.revision, storageFailed = false, streamFailed = false, terminal = false, suspended = false;\n            let diagnostics: GenerationTransportDiagnostics | undefined;\n            let diagnosticsAt = performance.now();\n            let agentProtocolText = '';\n            const events = new Map<string, string>();\n            const notify = () => { try {\n                deps.onSnapshot?.({ attemptId, visibleText: text, durableText: durable, durableRevision: revision, storageFailed, diagnostics });\n            }\n            catch { /* UI notification cannot alter durable accounting */ } };\n            const flush = () => {\n                if (storageFailed || text === durable)\n                    return;\n                try {\n                    const artifact = deps.repository.snapshot(attemptId, revision, text);\n                    revision = artifact.revision;\n                    durable = artifact.text;\n                }\n                catch {\n                    storageFailed = true;\n                    unsavedTails.set(attemptId, Object.freeze({ attemptId, artifactId: receipt.artifact!.artifactId,\n                        durableRevision: revision, text: text.slice(durable.length), failureCode: 'GENERATION_STORAGE_FAILED' }));\n                    failedRoots.add(run.rootActionId);\n                    controller.abort();\n                    try {\n                        deps.repository.block(run.rootActionId, 'GENERATION_STORAGE_FAILED');\n                    }\n                    catch { /* retain copyable tail in memory */ }\n                }\n                notify();\n            };\n            const retainInterruptedAgentText = () => {\n                if (request.agentToolNames && !text && !suspended)\n                    text = projectInterruptedAgentVisibleText(agentProtocolText, request.agentToolNames);\n            };\n            controllers.set(attemptId, { controller, rootId: run.rootActionId, flush: () => { retainInterruptedAgentText(); flush(); },\n                suspend: () => { receipt = deps.repository.receipt(attemptId); suspended = true; controller.abort(); } });\n            let timer: ReturnType<typeof setInterval> | undefined;\n            let deadline: ReturnType<typeof setTimeout> | undefined;\n            let removeAbortListener = () => { };\n            let timedOut = false;\n            try {\n                try {\n                    deps.repository.markDispatched(attemptId);\n                }\n                catch (error) {\n                    storageFailed = true;\n                    failedRoots.add(run.rootActionId);\n                    try {\n                        deps.repository.block(run.rootActionId, 'GENERATION_STORAGE_FAILED');\n                    }\n                    catch { /* The in-memory failure fence remains authoritative if storage is unavailable. */ }\n                    throw error;\n                }\n                timer = setInterval(flush, 1000);\n                const remaining = Math.max(0, receipt.budget.policy.maxActiveElapsedMs - deps.repository.budget(run.rootActionId).activeElapsedMs);\n                deadline = setTimeout(() => { timedOut = true; try {\n                    deps.repository.block(run.rootActionId, 'ROOT_BUDGET_EXHAUSTED');\n                }\n                catch {\n                    storageFailed = true;\n                    failedRoots.add(run.rootActionId);\n                } controller.abort(GENERATION_STOPPED); }, remaining);\n                const cancelled = new Promise<never>((_resolve, reject) => { const abort = () => reject(new Error('GENERATION_CANCELLED')); controller.signal.addEventListener('abort', abort, { once: true }); removeAbortListener = () => controller.signal.removeEventListener('abort', abort); });\n                const provider = deps.dispatch(request.providerRequest, { signal: controller.signal, onDiagnostics: value => {\n                        if (terminal || storageFailed || controller.signal.aborted) return;\n                        diagnostics = { ...value };\n                        diagnosticsAt = performance.now();\n                        notify();\n                    }, onReasoning: chunk => {\n                        if (terminal || storageFailed || controller.signal.aborted || !chunk) return;\n                        try { deps.onReasoning?.({ runId: run.runId, rootActionId: run.rootActionId, attemptId, text: chunk }); }\n                        catch { /* A display-only event cannot alter durable generation. */ }\n                    }, onVisible: event => {\n                        if (terminal || storageFailed || controller.signal.aborted)\n                            return;\n                        if (event.eventId) {\n                            const prior = events.get(event.eventId), current = JSON.stringify(event);\n                            if (prior) {\n                                if (prior !== current) {\n                                    streamFailed = true;\n                                    controller.abort();\n                                }\n                                return;\n                            }\n                            events.set(event.eventId, current);\n                        }\n                        if (/<\\/?think\\b/iu.test(event.text)) {\n                            streamFailed = true;\n                            controller.abort();\n                            return;\n                        }\n                        const previous = request.agentToolNames ? agentProtocolText : text;\n                        const next = event.kind === 'cumulative' ? event.text : previous + event.text;\n                        if (!next.startsWith(previous) || /<\\/?think\\b/iu.test(next)) {\n                            streamFailed = true;\n                            controller.abort();\n                            return;\n                        }\n                        if (request.agentToolNames) {\n                            // Protocol may arrive as XML, DSML or raw JSON. Do not stream it\n                            // through the user-artifact channel before its role is known.\n                            agentProtocolText = next;\n                            if (Buffer.byteLength(next, 'utf8') > 8 * 1024 * 1024) { streamFailed = true; controller.abort(); }\n                            return;\n                        }\n                        text = next;\n                        notify();\n                        if (Buffer.byteLength(text) - Buffer.byteLength(durable) >= 4096)\n                            flush();\n                    } });\n                const result = await Promise.race([provider, cancelled]);\n                if (controller.signal.aborted)\n                    throw new Error('GENERATION_CANCELLED');\n                let usage = streamFailed ? null : settleProviderUsage(result.usage, policy);\n                if (request.agentToolNames && result.finishReason === 'stop' && !streamFailed) {\n                    const parsed = parseAgentResponseProtocol(agentProtocolText, request.agentToolNames);\n                    text = parsed.visibleText;\n                    if (parsed.toolCalls.length > 64) throw new Error('GENERATION_AGENT_ACTION_LIMIT');\n                    usage = { ...usage!, agentResponse: { version: 1, visibleText: parsed.visibleText, toolCalls: parsed.toolCalls } };\n                }\n                else retainInterruptedAgentText();\n                flush();\n                receipt = deps.repository.settle(attemptId, usage, storageFailed ? 'error' : result.finishReason, storageFailed ? 'GENERATION_STORAGE_FAILED' : undefined, diagnostics);\n            }\n            catch (error) {\n                if (diagnostics && !diagnostics.endReason) diagnostics = { ...diagnostics, ...safeTransportError(error),\n                    elapsedMs: diagnostics.elapsedMs + Math.max(0, Math.round(performance.now() - diagnosticsAt)),\n                    endReason: controller.signal.aborted ? 'cancelled' : 'failed' };\n                retainInterruptedAgentText();\n                flush();\n                try {\n                    if (suspended) return { ...receipt, ...(storageFailed ? { unsavedTail: text.slice(durable.length) } : {}), failureCode: 'GENERATION_PROJECT_CLOSED' };\n                    const current = deps.repository.receipt(attemptId);\n                    if (current.attempt.status === 'dispatch-marked') {\n                        // Persist only stable categories, never provider text that may contain credentials or prompts.\n                        const networkCode = diagnostics?.causeCode ?? diagnostics?.errorCode;\n                        const network = Boolean(networkCode && /^(UND_ERR_|ECONN|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|ERR_STREAM_PREMATURE_CLOSE)/.test(networkCode))\n                            || error instanceof Error && /^(NETWORK_ERROR|ECONNRESET|ETIMEDOUT|FETCH_FAILED)$/.test(error.message);\n                        let known = 'GENERATION_PROVIDER_FAILED';\n                        if (error instanceof Error && isTerminalProviderFailure(error.message)) known = 'GENERATION_CONTEXT_LENGTH_EXCEEDED';\n                        else if (network) known = 'NETWORK_ERROR';\n                        const failureCode = storageFailed ? 'GENERATION_STORAGE_FAILED' : timedOut ? 'ROOT_BUDGET_EXHAUSTED'\n                            : streamFailed ? 'GENERATION_STREAM_INVALID' : controller.signal.aborted ? 'GENERATION_CANCELLED' : known;\n                        receipt = deps.repository.settle(attemptId, null, null, failureCode, diagnostics);\n                    }\n                    else\n                        receipt = current;\n                }\n                catch {\n                    storageFailed = true;\n                    failedRoots.add(run.rootActionId);\n                }\n            }\n            finally {\n                terminal = true;\n                if (timer)\n                    clearInterval(timer);\n                if (deadline)\n                    clearTimeout(deadline);\n                removeAbortListener();\n                controllers.delete(attemptId);\n            }\n            if (storageFailed)\n                return { ...receipt, unsavedTail: text.slice(durable.length), failureCode: 'GENERATION_STORAGE_FAILED' };\n            const finalReceipt = deps.repository.receipt(attemptId);\n            if (controller.signal.aborted)\n                return { ...finalReceipt, failureCode: finalReceipt.failureCode ?? (timedOut ? 'ROOT_BUDGET_EXHAUSTED' : 'GENERATION_CANCELLED') };\n            return finalReceipt;\n        })();\n        pending.set(key, operation);\n        try {\n            return await operation;\n        }\n        finally {\n            pending.delete(key);\n        }\n    };\n    const stopRoot = (rootId: string) => { for (const item of controllers.values())\n        if (item.rootId === rootId)\n            item.controller.abort(GENERATION_STOPPED); };\n    return {\n        open: (request: OpenGenerationRunRequest) => deps.repository.open(request), execute,\n        suspendForProjectClose: () => {\n            // Flush synchronously while the captured DB is still open, then\n            // persist unknown accounting before its owner closes the handle.\n            for (const item of controllers.values()) item.flush();\n            let failure: unknown;\n            try { deps.repository.recoverInterrupted(); } catch (error) { failure = error; }\n            for (const item of controllers.values()) {\n                try { item.suspend(); } catch (error) { failure ??= error; item.controller.abort(); }\n            }\n            if (unsavedTails.size) throw new Error('GENERATION_UNSAVED_TAIL_PRESENT');\n            if (failure) throw failure;\n        },\n        readUnsavedTails: (): readonly GenerationUnsavedTail[] => Object.freeze([...unsavedTails.values()]),\n        get: (runId: string) => deps.repository.get(runId),\n        readAttempt: (attemptId: string) => deps.repository.receipt(attemptId),\n        listCandidates: () => deps.repository.listCandidates(),\n        discardCandidate: (id: string) => {\n            deps.repository.discardCandidate(id);\n            for (const [attemptId, tail] of unsavedTails) if (tail.artifactId === id) unsavedTails.delete(attemptId);\n        },\n        pause: (rootId: string) => { deps.repository.pause(rootId); stopRoot(rootId); },\n        cancel: (rootId: string) => { deps.repository.pause(rootId, true); stopRoot(rootId); },\n        resume: async (runId: string, next: RunBinding) => { const old = deps.repository.get(runId); if (!isDeepStrictEqual(old.binding.fingerprint, next.fingerprint) || old.binding.contextSnapshotId !== next.contextSnapshotId || !isDeepStrictEqual(old.binding.sourceManifest, next.sourceManifest) || !deps.validateRecovery || !await deps.validateRecovery(old.binding, next))\n            throw new Error('GENERATION_RECOVERY_UNAUTHORIZED'); deps.repository.resume(runId, next); return deps.repository.get(runId); },\n        restart: (oldRootId: string, request: OpenGenerationRunRequest) => { deps.repository.pause(oldRootId, true); stopRoot(oldRootId); return deps.repository.open(request); },\n        recoverInterrupted: () => deps.repository.recoverInterrupted(),\n    };\n}\n"
